insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v001', 'abundant', 'Năm nay mùa xoài rất ABUNDANT, cả xóm ai cũng được hàng xóm cho một giỏ xoài chín mang về.', 'Dư thừa, nhiều hơn cần thiết', 'beginner', 850),
  ('v002', 'cognitive', 'Bài nghiên cứu tâm lý học này bàn về các chức năng COGNITIVE như trí nhớ, sự chú ý và khả năng suy luận.', 'Liên quan đến nhận thức, tri giác', 'beginner', 870),
  ('v003', 'dilemma', 'Trước một DILEMMA giữa việc chọn nghề theo sở thích hay theo mức lương cao, Minh đã hỏi ý kiến cả gia đình.', 'Tình huống khó xử, lưỡng nan', 'beginner', 820),
  ('v004', 'feasible', 'Cả nhóm xem lại kế hoạch làm dự án trong hai tuần, nhưng thấy mục tiêu này không FEASIBLE nếu chỉ có ba người.', 'Khả thi, có thể thực hiện được', 'beginner', 880),
  ('v005', 'inevitable', 'Lịch thi cuối kỳ dày đặc, nên việc thức khuya ôn bài gần như INEVITABLE với cả lớp.', 'Không thể tránh khỏi', 'beginner', 890),
  ('v006', 'pragmatic', 'Thay vì mua xe mới, chị Lan chọn cách PRAGMATIC hơn là sửa lại chiếc xe cũ để đi làm mỗi ngày.', 'Thực dụng, thực tế', 'beginner', 920),
  ('v007', 'ambiguous', 'Tin nhắn của thầy viết khá AMBIGUOUS, em không biết hạn nộp bài là thứ Sáu hay thứ Bảy.', 'Mơ hồ, không rõ ràng', 'beginner', 950),
  ('v008', 'resilient', 'Dù gặp nhiều thất bại trong năm đầu, bạn tôi vẫn RESILIENT và sớm quay lại với công việc.', 'Kiên cường, phục hồi nhanh', 'beginner', 940),
  ('v009', 'tedious', 'Đối chiếu hàng trăm dòng số liệu trong bảng tính là một công việc TEDIOUS, nhưng cần làm cẩn thận.', 'Buồn tẻ, nhàm chán', 'beginner', 910),
  ('v010', 'subtle', 'Sự thay đổi màu sắc trong bức tranh rất SUBTLE, phải nhìn kỹ mới thấy được sự khác biệt.', 'Tinh tế, khó nhận ra', 'beginner', 930),
  ('v011', 'meticulous', 'Chị kế toán kiểm tra từng hóa đơn một cách METICULOUS, không bỏ sót một đồng nào trong sổ sách.', 'Tỉ mỉ, cẩn thận', 'intermediate', 1050),
  ('v012', 'ubiquitous', 'Điện thoại thông minh giờ đã UBIQUITOUS, từ quán cà phê đến trường học đâu cũng thấy người cúi nhìn màn hình.', 'Phổ biến khắp nơi', 'intermediate', 1080),
  ('v013', 'ephemeral', 'Niềm vui khi nhận được lời khen từ thầy thường EPHEMERAL, chỉ kéo dài vài ngày rồi lại lo bài tiếp theo.', 'Phù du, ngắn ngủi', 'intermediate', 1100),
  ('v014', 'eloquent', 'Bạn Hương trình bày đề tài trước lớp rất ELOQUENT, cả giảng đường vỗ tay khi cô kết thúc bài nói.', 'Hùng biện, lưu loát', 'intermediate', 1020),
  ('v015', 'plausible', 'Lời giải thích của anh Tuấn về việc đến muộn nghe khá PLAUSIBLE, nên tổ trưởng không hỏi thêm gì.', 'Hợp lý, đáng tin', 'intermediate', 1010),
  ('v016', 'scrutinize', 'Trước khi ký hợp đồng thuê nhà, mẹ tôi SCRUTINIZE từng điều khoản và từng khoản phí phát sinh.', 'Xem xét kỹ lưỡng', 'intermediate', 1040),
  ('v017', 'candid', 'Trong buổi góp ý, cô giáo nhận xét rất CANDID về bài luận của em, và em thấy điều đó thực sự hữu ích.', 'Thẳng thắn, chân thành', 'intermediate', 1030),
  ('v018', 'contemplate', 'Sau khi tốt nghiệp, Hoàng thường ngồi bên cửa sổ và CONTEMPLATE con đường mình muốn theo đuổi.', 'Suy ngẫm, trầm tư', 'intermediate', 1060),
  ('v019', 'mundane', 'Công việc hằng ngày của chị là nhập số liệu vào bảng tính, một việc MUNDANE nhưng cần thật cẩn thận.', 'Tầm thường, nhàm chán', 'intermediate', 1000),
  ('v020', 'inherent', 'Mọi nghề đều có những rủi ro INHERENT, vì vậy bạn nên chuẩn bị kế hoạch dự phòng ngay từ đầu.', 'Vốn có, cố hữu', 'intermediate', 1070),
  ('v021', 'conundrum', 'Cả nhóm đang đứng trước một CONUNDRUM: ngân sách có hạn nhưng khách hàng lại đòi thêm tính năng mới.', 'Vấn đề hóc búa', 'intermediate', 1150),
  ('v022', 'exacerbate', 'Thức khuya chơi game trước kỳ thi chỉ EXACERBATE tình trạng mệt mỏi và khó tập trung học bài.', 'Làm tệ hại thêm', 'intermediate', 1180),
  ('v023', 'mitigate', 'Để MITIGATE cơn đau đầu do học nhiều, Lan tập thói quen nghỉ mắt mỗi nửa tiếng.', 'Giảm nhẹ, làm dịu', 'intermediate', 1120),
  ('v024', 'nuance', 'Khi đọc truyện tiếng Anh, em phải chú ý đến từng NUANCE trong lời thoại để hiểu đúng ý nhân vật.', 'Sắc thái nhỏ', 'intermediate', 1140),
  ('v025', 'prolific', 'Cô tác giả này rất PROLIFIC, mỗi năm ra mắt vài cuốn sách và nhiều truyện ngắn khác nhau.', 'Hiệu suất cao, đẻ nhiều', 'intermediate', 1160),
  ('v026', 'redundant', 'Đoạn văn này có vài câu REDUNDANT, bạn có thể bỏ đi mà vẫn giữ nguyên ý chính của bài.', 'Thừa thãi', 'intermediate', 1110),
  ('v027', 'tangible', 'Sau ba tháng luyện tập, em đã có kết quả TANGIBLE: điểm thi tiếng Anh tăng từ 5.5 lên 6.5.', 'Hữu hình, rõ rệt', 'intermediate', 1130),
  ('v028', 'zenith', 'Năm 2019, công ty khởi nghiệp của anh Nam đạt ZENITH về doanh thu, rồi sau đó dần chững lại.', 'Đỉnh cao', 'intermediate', 1190),
  ('v029', 'coherent', 'Bài thuyết trình của nhóm được chuẩn bị rất COHERENT, mỗi slide nối tiếp slide trước một cách hợp lý.', 'Mạch lạc, logic', 'intermediate', 1170),
  ('v030', 'arbitrary', 'Thầy chấm điểm theo cách ARBITRARY: bài dài bị trừ điểm còn bài ngắn lại được cộng, không có tiêu chí rõ.', 'Tùy hứng, tùy tiện', 'intermediate', 1100),
  ('v031', 'belligerent', 'Trong buổi tranh luận, anh ấy trở nên BELLIGERENT khi bị phản đối, khiến cả phòng họp im lặng.', 'Hiếu chiến, hung hăng', 'advanced', 1250),
  ('v032', 'elucidate', 'Giáo sư ELUCIDATE cách hoạt động của thuật toán bằng một ví dụ đơn giản, cả lớp hiểu ngay.', 'Làm sáng tỏ, giải thích rõ', 'advanced', 1220),
  ('v033', 'esoteric', 'Cuốn sách triết học này dùng nhiều thuật ngữ ESOTERIC, đọc hai trang là em đã phải tra từ điển.', 'Bí truyền, chuyên sâu khó hiểu', 'advanced', 1280),
  ('v034', 'gregarious', 'Mai là người rất GREGARIOUS nên bạn mới vào lớp nhanh chóng quen và rủ nhau đi ăn trưa.', 'Hòa đồng, thích giao du', 'advanced', 1240),
  ('v035', 'impetuous', 'Anh Bình hay IMPETUOUS khi mua sắm, thấy quảng cáo là đặt hàng ngay mà không so sánh giá.', 'Hấp tấp, bốc đồng', 'advanced', 1260),
  ('v036', 'juxtapose', 'Trong bài tiểu luận, em JUXTAPOSE hai bức tranh của hai họa sĩ để thấy rõ phong cách khác nhau.', 'Đặt cạnh nhau để so sánh', 'advanced', 1230),
  ('v037', 'malevolent', 'Nhân vật phản diện trong phim có nụ cười MALEVOLENT, khiến khán giả ai cũng thấy ghét.', 'Độc ác, có ác ý', 'advanced', 1270),
  ('v038', 'obfuscate', 'Bản hợp đồng dùng quá nhiều điều khoản phức tạp, như thể cố tình OBFUSCATE điều quan trọng nhất.', 'Làm mờ mịt, che giấu', 'advanced', 1290),
  ('v039', 'parsimony', 'Ông chủ nổi tiếng với PARSIMONY, đến cả tiền in tài liệu cũng cắt giảm từng tờ một.', 'Sự bủn xỉn, keo kiệt', 'advanced', 1210),
  ('v040', 'quintessential', 'Bánh mì với pate và chả lụa là món QUINTESSENTIAL của bữa sáng nhiều người Việt.', 'Tinh túy, điển hình', 'advanced', 1200)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v041', 'recalcitrant', 'Cậu học trò lớp bên rất RECALCITRANT, nhắc mãi mà vẫn không chịu nộp bài đúng hạn.', 'Ngoan cố, bướng bỉnh', 'expert', 1350),
  ('v042', 'salient', 'Điểm SALIENT trong bài báo cáo của chị Hà là phần số liệu được trình bày bằng biểu đồ rất rõ ràng.', 'Nổi bật, đáng chú ý', 'expert', 1320),
  ('v043', 'taciturn', 'Anh Trung rất TACITURN trong các buổi họp, thường chỉ gật đầu hoặc nói vài từ ngắn gọn.', 'Ít nói, lầm lì', 'expert', 1340),
  ('v044', 'vicarious', 'Không đi được Nhật Bản, Mai xem video du lịch để có cảm giác VICARIOUS khi ngắm núi Phú Sĩ.', 'Trải nghiệm gián tiếp', 'expert', 1310),
  ('v045', 'zealot', 'Trong nhóm lập trình có một ZEALOT luôn cho rằng ngôn ngữ của mình là tốt nhất, dù không ai hỏi.', 'Người cuồng tín', 'expert', 1330),
  ('v046', 'ameliorate', 'Sau khi thay đổi cách giao tiếp, chị đã AMELIORATE mối quan hệ với các đồng nghiệp trong phòng.', 'Cải thiện, làm tốt hơn', 'expert', 1360),
  ('v047', 'cacophony', 'Giờ tan học, tiếng xe máy, tiếng trống trường và tiếng rao hàng tạo thành một CACOPHONY ồn ào trước cổng.', 'Âm thanh hỗn tạp, chói tai', 'expert', 1380),
  ('v048', 'dogmatic', 'Thầy hướng dẫn rất DOGMATIC, chỉ chấp nhận một cách làm bài duy nhất và không nghe ý kiến khác.', 'Giáo điều, độc đoán', 'expert', 1300),
  ('v049', 'enervate', 'Chạy bộ dưới nắng trưa khiến tôi ENERVATED, về nhà chỉ muốn nằm im trên giường.', 'Làm suy yếu, làm kiệt sức', 'expert', 1390),
  ('v050', 'hackneyed', 'Bài phát biểu của ông hiệu trưởng toàn câu HACKNEYED, nghe đi nghe lại những điều ai cũng đã biết.', 'Sáo rỗng, tầm thường', 'expert', 1410),
  ('v051', 'grandiloquent', 'Bài đăng của cậu ấy GRANDILOQUENT quá, chỉ kể chuyện đi ăn sáng mà viết như một bài thơ sử thi.', 'Khoa trương, hoa mỹ', 'expert', 1450),
  ('v052', 'iconoclast', 'Chị Thu là một ICONOCLAST trong nhóm thiết kế, luôn đặt câu hỏi vì sao mọi thứ phải làm theo cách cũ.', 'Người đả phá những quan điểm cũ', 'expert', 1440),
  ('v053', 'laconic', 'Anh ấy trả lời email rất LACONIC, chỉ vài chữ như Đã nhận hoặc Chiều gặp nhé.', 'Ngắn gọn, súc tích', 'expert', 1430),
  ('v054', 'obsequious', 'Nhân viên mới rất OBSEQUIOUS với sếp, lúc nào cũng khen và gật đầu, khiến đồng nghiệp thấy không thoải mái.', 'Khúm núm, xu nịnh', 'expert', 1460),
  ('v055', 'pernicious', 'Lướt mạng xã hội trước khi ngủ có thể là thói quen PERNICIOUS, làm giấc ngủ kém đi mà mình không nhận ra.', 'Độc hại, nguy hiểm ngầm', 'expert', 1470),
  ('v056', 'quixotic', 'Kế hoạch tự học ba ngoại ngữ trong một tháng nghe QUIXOTIC, nên tôi khuyên bạn đặt mục tiêu nhỏ hơn.', 'Viển vông, không thực tế', 'expert', 1480),
  ('v057', 'risible', 'Lý do cậu ấy đưa ra nghe RISIBLE đến mức cả lớp bật cười, nhưng không ai nói gì thêm.', 'Đáng cười, lố bịch', 'expert', 1400),
  ('v058', 'sycophant', 'Trong công ty có một SYCOPHANT lúc nào cũng khen sếp, nên đồng nghiệp thường không tin lời anh ta.', 'Kẻ nịnh hót', 'expert', 1490),
  ('v059', 'vitriolic', 'Bình luận VITRIOLIC dưới bài viết của cô làm cô buồn cả tuần, dù nội dung chỉ là chia sẻ cách nấu ăn.', 'Châm chọc, cay độc', 'expert', 1460),
  ('v060', 'abstruse', 'Bài giảng về lý thuyết tập hợp hôm nay ABSTRUSE quá, cả lớp nghe xong vẫn chưa hiểu ý thầy.', 'Thâm thúy, khó hiểu', 'expert', 1490),
  ('v061', 'anxious', 'Trước buổi phỏng vấn, Linh cảm thấy ANXIOUS, cứ kiểm tra lại hồ sơ ba bốn lần.', 'Lo lắng, bồn chồn', 'beginner', 810),
  ('v062', 'blunt', 'Anh Đức góp ý rất BLUNT: anh nói thẳng rằng bản thiết kế chưa đạt và cần làm lại từ đầu.', 'Thẳng thắn đến mức thô lỗ', 'beginner', 820),
  ('v063', 'cautious', 'Khi mua hàng trên mạng, bạn nên CAUTIOUS với người bán giá rẻ bất thường và đòi chuyển khoản trước.', 'Thận trọng, cẩn thận', 'beginner', 815),
  ('v064', 'demand', 'Khách hàng DEMAND được giảm giá và giao hàng trong hôm nay, dù đơn đã được xác nhận từ trước.', 'Yêu cầu, đòi hỏi', 'beginner', 830),
  ('v065', 'efficient', 'Lập danh sách công việc theo thứ tự ưu tiên là cách EFFICIENT để làm xong bài tập trong một buổi tối.', 'Hiệu quả, năng suất', 'beginner', 840),
  ('v066', 'flexible', 'Công ty cho phép nhân viên làm việc FLEXIBLE: có thể đến văn phòng sớm hoặc làm ở nhà vào buổi chiều.', 'Linh hoạt, dễ thích nghi', 'beginner', 835),
  ('v067', 'genuine', 'Lời xin lỗi của anh ấy nghe rất GENUINE, không giống kiểu nói cho qua chuyện, nên tôi bỏ qua.', 'Thật thà, chân thành', 'beginner', 845),
  ('v068', 'hesitate', 'Nếu có cơ hội học bổng, đừng HESITATE khi nộp hồ sơ, vì càng chần chừ thì càng dễ lỡ hạn.', 'Do dự, ngập ngừng', 'beginner', 830),
  ('v069', 'impact', 'Chương trình tình nguyện mùa hè này có IMPACT lớn đến các em học sinh vùng cao, nhiều em đọc viết tốt hơn.', 'Tác động, ảnh hưởng mạnh', 'beginner', 825),
  ('v070', 'justify', 'Bạn không cần JUSTIFY lý do nghỉ phép ngắn ngày, chỉ cần báo trước cho trưởng nhóm là được.', 'Biện minh, thanh minh', 'beginner', 850),
  ('v071', 'keen', 'Lan rất KEEN tham gia câu lạc bộ đọc sách, tuần nào cũng đến sớm để chuẩn bị bài thảo luận.', 'Hăng hái, nhiệt tình', 'beginner', 835),
  ('v072', 'logical', 'Thầy yêu cầu mỗi bước giải toán phải LOGICAL, từ giả thiết đến kết luận đều có lý do rõ ràng.', 'Hợp lý, theo logic', 'beginner', 840),
  ('v073', 'massive', 'Thành phố này có một khu chợ MASSIVE, trải dài cả mấy con phố với hàng nghìn gian hàng.', 'Khổng lồ, to lớn', 'beginner', 820),
  ('v074', 'neglect', 'Vì quá bận học cho kỳ thi, em đã NEGLECT việc tập thể dục và ăn uống đều đặn.', 'Bỏ bê, xao nhãng', 'beginner', 855),
  ('v075', 'obvious', 'Lỗi chính tả trong tiêu đề là OBVIOUS, ai xem qua cũng thấy ngay, nên cả nhóm sửa lại liền.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v076', 'persistent', 'Nhà trường nhắc đóng học phí rất PERSISTENT, dù phụ huynh đã thanh toán từ tuần trước.', 'Kiên trì, dai dẳng', 'beginner', 860),
  ('v077', 'relevant', 'Khi làm bài nghiên cứu, bạn chỉ nên trích những số liệu RELEVANT đến câu hỏi chính, bỏ phần còn lại.', 'Liên quan, phù hợp', 'beginner', 845),
  ('v078', 'significant', 'Việc luyện nói mỗi ngày đã mang lại tiến bộ SIGNIFICANT cho Hải trong vòng ba tháng.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v079', 'tolerate', 'Làm việc trong team có thể gặp nhiều người khác tính, nhưng bạn không nên TOLERATE sự thiếu tôn trọng.', 'Tha thứ, chịu đựng', 'beginner', 855),
  ('v080', 'utilize', 'Thư viện trường mở cửa đến tối, sinh viên nên UTILIZE không gian này để ôn bài theo nhóm.', 'Sử dụng, tận dụng', 'beginner', 860)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v081', 'valid', 'Vé của bạn vẫn VALID đến hết tháng này, nên bạn có thể đổi lịch chiếu phim mà không mất phí.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v082', 'willing', 'Anh Quân WILLING giúp các bạn trẻ chuẩn bị phỏng vấn, còn sắp xếp cả thời gian buổi tối.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v083', 'abstract', 'Bức tranh này rất ABSTRACT, chỉ có các mảng màu và đường nét, nên mỗi người có thể hiểu một cách.', 'Trừu tượng', 'beginner', 870),
  ('v084', 'benefit', 'Công ty cung cấp nhiều BENEFIT cho nhân viên như bảo hiểm sức khỏe, hỗ trợ tiền ăn trưa và gói học tập.', 'Lợi ích, phúc lợi', 'beginner', 825),
  ('v085', 'confident', 'Sau khi luyện thuyết trình ba lần, Minh CONFIDENT hơn hẳn và trả lời các câu hỏi rất trôi chảy.', 'Tự tin', 'beginner', 835),
  ('v086', 'diverse', 'Lớp học tiếng Anh của tôi có học viên DIVERSE về nghề nghiệp, từ bác sĩ đến nhân viên ngân hàng.', 'Đa dạng', 'beginner', 865),
  ('v087', 'evident', 'Sau một đêm thức trắng học bài, quầng thâm dưới mắt Hà rất EVIDENT, ai nhìn cũng biết cô thiếu ngủ.', 'Rõ ràng, hiển nhiên', 'beginner', 855),
  ('v088', 'focus', 'Để FOCUS vào bài viết, Hương tắt thông báo điện thoại và đặt đồng hồ hẹn 25 phút.', 'Tập trung', 'beginner', 820),
  ('v089', 'generate', 'Phần mềm này có thể GENERATE báo cáo tự động từ bảng số liệu, giúp nhân viên tiết kiệm hàng giờ làm việc.', 'Tạo ra', 'beginner', 845),
  ('v090', 'highlight', 'Điểm HIGHLIGHT của chuyến đi là buổi tối ngắm pháo hoa bên bờ sông cùng cả nhóm bạn.', 'Điểm nhấn, nổi bật', 'beginner', 830),
  ('v091', 'advocating', 'Trong buổi họp nhóm, chị ấy ADVOCATING cho việc dành thời gian học kỹ năng mới cho nhân viên thay vì chỉ làm việc theo kế hoạch cũ.', 'Ủng hộ, vận động cho', 'intermediate', 960),
  ('v092', 'ambivalent', 'Sau khi nhận lời mời làm việc mới, tôi cảm thấy AMBIVALENT: vừa mừng vì lương cao hơn, vừa tiếc vì phải rời nhóm cũ đã gắn bó nhiều năm.', 'Mâu thuẫn, vừa thích vừa ghét', 'intermediate', 980),
  ('v093', 'analogous', 'Cách tổ chức các thư mục trong dự án này khá ANALOGOUS với cách sắp xếp sách trong thư viện, nên tôi nhanh chóng làm quen được.', 'Tương tự, giống như', 'intermediate', 1050),
  ('v094', 'articulate', 'Bạn ấy rất ARTICULATE khi thuyết trình, mỗi ý đều được trình bày rõ ràng và mạch lạc, nên cả lớp dễ theo dõi bài nói.', 'Diễn đạt lưu loát', 'intermediate', 1000),
  ('v095', 'assertive', 'Trong buổi phỏng vấn, bạn nên ASSERTIVE khi nói về kinh nghiệm của mình, tức là nói rõ điều mình làm được và thể hiện sự tự tin.', 'Quyết đoán, tự tin khẳng định', 'intermediate', 970),
  ('v096', 'biased', 'Bài đánh giá này khá BIASED vì tác giả chỉ nêu ưu điểm của một sản phẩm mà bỏ qua những hạn chế đã được ghi nhận.', 'Thiên vị, có thành kiến', 'intermediate', 960),
  ('v097', 'bureaucratic', 'Thủ tục xin xác nhận cư trú ở phường khá BUREAUCRATIC, phải nộp nhiều bản sao giấy tờ và đến nhiều lần mới xong.', 'Quan liêu, nhiều thủ tục', 'intermediate', 1080),
  ('v098', 'catalyst', 'Chuyến đi tình nguyện ở vùng núi đã trở thành CATALYST giúp anh thay đổi cách nhìn về công việc và về những điều mình thật sự cần.', 'Chất xúc tác, nhân tố kích thích', 'intermediate', 1020),
  ('v099', 'chronic', 'Anh ấy bị đau lưng CHRONIC vì ngồi máy tính quá lâu, nên đã đi khám và đổi sang một chiếc ghế có tựa lưng tốt hơn.', 'Mãn tính, kinh niên', 'intermediate', 975),
  ('v100', 'comprehensive', 'Cuốn sách hướng dẫn nấu ăn này rất COMPREHENSIVE, từ cách chọn nguyên liệu đến các món cơ bản dành cho người mới bắt đầu.', 'Toàn diện, bao quát', 'intermediate', 990),
  ('v101', 'contentious', 'Việc có nên cho học sinh dùng điện thoại trong giờ học là một chủ đề CONTENTIOUS, nhiều phụ huynh và giáo viên có ý kiến khác nhau.', 'Gây tranh cãi', 'intermediate', 1060),
  ('v102', 'counterproductive', 'Thức khuya để học bài nhưng sáng hôm sau ngủ bù cả buổi thì cách làm này thật COUNTERPRODUCTIVE, vì kết quả học tập không tăng.', 'Phản tác dụng', 'intermediate', 1100),
  ('v103', 'credible', 'Trang bán hàng này không ghi địa chỉ hay số điện thoại liên hệ, nên nhìn không CREDIBLE, bạn nên cân nhắc kỹ trước khi đặt hàng.', 'Đáng tin', 'intermediate', 980),
  ('v104', 'cumulative', 'Học mỗi ngày 20 phút tiếng Anh nghe có vẻ ít, nhưng hiệu quả CUMULATIVE sau vài tháng sẽ thấy rõ khi bạn đọc hiểu tốt hơn.', 'Tích lũy, dồn lại', 'intermediate', 1040),
  ('v105', 'cynical', 'Sau nhiều lần được hứa suông về việc thăng chức, anh ấy trở nên CYNICAL và không còn tin vào những lời cam kết của công ty.', 'Hoài nghi, yếm thế', 'intermediate', 965),
  ('v106', 'decisive', 'Trong nhóm bốn người, chị ấy là người DECISIVE nhất, nhanh chóng chọn chủ đề và phân công việc để cả nhóm kịp hạn nộp bài.', 'Quyết đoán', 'intermediate', 970),
  ('v107', 'detrimental', 'Thức khuya liên tục có thể DETRIMENTAL đến sức khỏe, làm bạn mệt mỏi, khó tập trung và giảm chất lượng công việc mỗi ngày.', 'Có hại, bất lợi', 'intermediate', 1030),
  ('v108', 'dynamic', 'Ngành marketing là một môi trường DYNAMIC, xu hướng mới xuất hiện gần như mỗi tuần nên người làm nghề phải cập nhật liên tục.', 'Năng động, thay đổi liên tục', 'intermediate', 955),
  ('v109', 'elaborate', 'Bạn có thể ELABORATE thêm về kinh nghiệm làm việc nhóm trong hồ sơ xin việc không? Nhà tuyển dụng muốn hiểu rõ hơn về vai trò của bạn.', 'Giải thích chi tiết', 'intermediate', 990),
  ('v110', 'empirical', 'Bài báo đưa ra nhiều bằng chứng EMPIRICAL từ thí nghiệm thực tế, nên kết luận của nó được nhiều người trong ngành đánh giá là đáng tin.', 'Dựa trên thực tế, thực nghiệm', 'intermediate', 1070),
  ('v111', 'explicit', 'Trong hợp đồng thuê nhà có điều khoản EXPLICIT về việc hoàn lại tiền cọc, nên hai bên không cần tranh cãi khi trả nhà.', 'Rõ ràng, dứt khoát', 'intermediate', 1000),
  ('v112', 'formidable', 'Đội đối thủ lần này là một đối thủ FORMIDABLE, họ có lối chơi nhanh, đội hình mạnh và rất nhiều kinh nghiệm thi đấu.', 'Đáng gờm', 'intermediate', 1050),
  ('v113', 'fragmented', 'Thị trường giao đồ ăn khá FRAGMENTED, có rất nhiều ứng dụng nhỏ nhưng chưa có đơn vị nào chiếm được thị phần lớn.', 'Phân mảnh, rời rạc', 'intermediate', 1020),
  ('v114', 'fundamental', 'Hiểu các khái niệm FUNDAMENTAL về kế toán cá nhân là bước đầu tiên để bạn quản lý chi tiêu hằng tháng tốt hơn và tiết kiệm đều.', 'Cơ bản, thiết yếu', 'intermediate', 960),
  ('v115', 'hypothetical', 'Thầy giáo đưa ra một tình huống HYPOTHETICAL: nếu bạn có 100 triệu đồng thì bạn sẽ dùng số tiền đó để làm gì, và vì sao?', 'Giả định, giả thuyết', 'intermediate', 1080),
  ('v116', 'implicit', 'Trong email không viết rõ, nhưng câu cuối có một ý IMPLICIT rằng khách hàng muốn nhận hàng trước thứ Sáu tuần này.', 'Ngầm định, ẩn ý', 'intermediate', 1040),
  ('v117', 'indispensable', 'Chiếc máy tính xách tay này INDISPENSABLE với tôi, vì tôi dùng nó để học, làm việc và chỉnh sửa ảnh mỗi ngày.', 'Không thể thiếu', 'intermediate', 1090),
  ('v118', 'integrate', 'Nhóm kỹ thuật cần INTEGRATE hệ thống thanh toán mới vào ứng dụng hiện tại trước khi ra mắt phiên bản mới vào tháng sau.', 'Tích hợp', 'intermediate', 970),
  ('v119', 'intuitive', 'Ứng dụng đặt xe này có giao diện rất INTUITIVE, lần đầu dùng mà tôi vẫn biết bấm vào đâu để đặt xe đến sân bay.', 'Trực quan, dễ hiểu', 'intermediate', 1010),
  ('v120', 'leverage', 'Thay vì viết lại từ đầu, nhóm quyết định LEVERAGE các thư viện có sẵn để tiết kiệm thời gian và công sức phát triển sản phẩm.', 'Tận dụng lợi thế', 'intermediate', 1000)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v121', 'modicum', 'Khi học một ngôn ngữ mới, bạn chỉ cần có một MODICUM kiên nhẫn, vì tiến bộ thường đến chậm nhưng đều đặn sau vài tuần.', 'Một chút, lượng nhỏ tối thiểu', 'intermediate', 1030),
  ('v122', 'momentum', 'Sau tuần đầu học đều đặn, tôi cảm thấy MOMENTUM tăng dần, nên việc học buổi tối không còn khó khăn như lúc mới bắt đầu.', 'Đà tiến, sức đẩy', 'intermediate', 990),
  ('v123', 'monotonous', 'Công việc nhập số liệu vào bảng tính khá MONOTONOUS, ngày nào cũng giống nhau nên người làm dễ thấy chán và mệt mỏi.', 'Đơn điệu, tẻ nhạt', 'intermediate', 975),
  ('v124', 'navigate', 'Khách du lịch lần đầu đến Hà Nội có thể dùng bản đồ trên điện thoại để NAVIGATE qua các con phố cổ mà không bị lạc.', 'Điều hướng, tìm cách vượt qua', 'intermediate', 960),
  ('v125', 'objective', 'Để đánh giá một quán ăn một cách OBJECTIVE, bạn nên xem xét cả chất lượng món ăn, mức giá và cách phục vụ, không chỉ cảm nhận riêng.', 'Khách quan, mục tiêu', 'intermediate', 950),
  ('v126', 'overwhelming', 'Lịch học dày đặc với ba bài kiểm tra trong một tuần khiến tôi cảm thấy OVERWHELMING và không biết nên bắt đầu ôn từ đâu.', 'Choáng ngợp, quá tải', 'intermediate', 980),
  ('v127', 'paradox', 'Càng có nhiều lựa chọn trên mạng, tôi càng khó quyết định khi mua đồ, đúng là một PARADOX của thời đại mua sắm trực tuyến.', 'Nghịch lý', 'intermediate', 1050),
  ('v128', 'perceive', 'Nhiều khách hàng PERCEIVE quán cà phê này là sang trọng, dù giá không cao, vì không gian được bày trí đẹp và yên tĩnh.', 'Nhận thức, cảm nhận', 'intermediate', 1010),
  ('v129', 'perpetual', 'Thành phố có tình trạng kẹt xe PERPETUAL vào giờ tan tầm, nên tôi thường phải về nhà muộn hơn cả tiếng so với dự định.', 'Liên tục, vĩnh cửu', 'intermediate', 1060),
  ('v130', 'prevalent', 'Thói quen dùng điện thoại trước khi ngủ đang PREVALENT trong nhóm sinh viên, nhiều bạn không để ý đến ảnh hưởng của nó đến giấc ngủ.', 'Phổ biến, thịnh hành', 'intermediate', 1020),
  ('v131', 'proactive', 'Thay vì đợi thầy nhắc, cả nhóm nên PROACTIVE liên hệ để hỏi rõ thời hạn nộp bài và các yêu cầu của đề tài.', 'Chủ động', 'intermediate', 975),
  ('v132', 'profound', 'Chuyến đi một mình qua miền Tây đã có một tác động PROFOUND đến cách tôi nhìn nhận cuộc sống và những ưu tiên trong công việc.', 'Sâu sắc, thâm thúy', 'intermediate', 1040),
  ('v133', 'rational', 'Trước khi mua xe, bạn nên đưa ra một quyết định RATIONAL dựa trên ngân sách, nhu cầu đi lại thực tế và chi phí bảo dưỡng.', 'Hợp lý, dựa trên lý trí', 'intermediate', 965),
  ('v134', 'skeptical', 'Tôi khá SKEPTICAL về quảng cáo giảm giá 90%, nên đã so sánh giá với nhiều trang khác trước khi quyết định mua hàng.', 'Hoài nghi, ngờ vực', 'intermediate', 990),
  ('v135', 'spontaneous', 'Cả nhóm bạn quyết định đi biển SPONTANEOUS vào cuối tuần này, chỉ mất một buổi chiều để chuẩn bị đồ và đặt phòng nghỉ.', 'Ngẫu hứng, bột phát', 'intermediate', 1000),
  ('v136', 'subjective', 'Đánh giá một bộ phim là khá SUBJECTIVE, người này thích cốt truyện còn người kia lại thích diễn xuất và phần âm nhạc hơn.', 'Chủ quan', 'intermediate', 975),
  ('v137', 'sustainable', 'Học đều đặn mỗi ngày 2 giờ suốt cả năm là cách học SUSTAINABLE hơn nhiều so với việc học dồn ép trước kỳ thi.', 'Bền vững', 'intermediate', 955),
  ('v138', 'transparent', 'Công ty đăng công khai bảng tiêu chí xét thưởng, giúp nhân viên thấy quy trình này TRANSPARENT và công bằng hơn trước.', 'Minh bạch', 'intermediate', 970),
  ('v139', 'trivial', 'Đừng mất thời gian tranh luận về những chuyện TRIVIAL như màu chữ trong bản trình chiếu, hãy tập trung vào nội dung chính.', 'Tầm thường, vụn vặt', 'intermediate', 960),
  ('v140', 'unprecedented', 'Lượng đơn đặt hàng tăng gấp ba chỉ trong một tuần là con số UNPRECEDENTED đối với cửa hàng nhỏ của chúng tôi từ trước đến nay.', 'Chưa từng có tiền lệ', 'intermediate', 1070),
  ('v141', 'vulnerable', 'Tài khoản dùng mật khẩu đơn giản rất VULNERABLE, nên bạn nên bật xác thực hai lớp cho các ứng dụng và thư quan trọng.', 'Dễ bị tổn thương', 'intermediate', 1010),
  ('v142', 'warranted', 'Sự lo lắng của phụ huynh về lịch thi là WARRANTED, vì nhà trường đã thay đổi thời gian thi đến hai lần trong cùng một tháng.', 'Có cơ sở, được cho phép', 'intermediate', 1080),
  ('v143', 'acrimonious', 'Cuộc họp về ngân sách kết thúc trong không khí ACRIMONIOUS, hai bên đều không chịu nhường nhau dù đã kéo dài đến tối muộn.', 'Cay nghiệt, đầy ác ý', 'advanced', 1150),
  ('v144', 'admonish', 'Thầy giáo ADMONISH học sinh vì đến lớp muộn, nhưng vẫn nhắc nhẹ nhàng và dặn lần sau nên đi sớm hơn một chút.', 'Cảnh cáo, khiển trách nhẹ', 'advanced', 1200),
  ('v145', 'affluent', 'Khu này có nhiều biệt thự và trường học tốt, nên được xem là khu dân cư AFFLUENT nhất của thành phố trong nhiều năm qua.', 'Giàu có, thịnh vượng', 'advanced', 1120),
  ('v146', 'alleviate', 'Việc chia đều công việc giữa hai người giúp ALLEVIATE áp lực cho từng cá nhân, nhất là vào thời điểm cao điểm cuối tháng.', 'Giảm nhẹ, làm vơi bớt', 'advanced', 1140),
  ('v147', 'altruistic', 'Anh ấy tham gia lớp dạy kèm miễn phí với động cơ ALTRUISTIC, chỉ mong các em nhỏ trong xóm có thêm cơ hội học tập.', 'Vị tha, không vụ lợi', 'advanced', 1180),
  ('v148', 'aberrant', 'Máy chủ có một hành vi ABERRANT vào lúc nửa đêm, nên đội kỹ thuật phải kiểm tra lại nhật ký hệ thống để tìm nguyên nhân.', 'Bất thường, lệch lạc', 'advanced', 1130),
  ('v149', 'anachronistic', 'Việc bắt nhân viên ghi giờ vào và giờ ra từng phút trong thời buổi làm việc từ xa là một cách làm ANACHRONISTIC, không còn phù hợp.', 'Lỗi thời, sai thời điểm', 'advanced', 1280),
  ('v150', 'anecdotal', 'Tin đồn công ty sắp tăng lương chỉ là thông tin ANECDOTAL từ vài người, chưa có thông báo chính thức nào từ ban lãnh đạo.', 'Dựa trên lời kể, không chính thức', 'advanced', 1160),
  ('v151', 'anomaly', 'Kết quả thử nghiệm hôm nay có một ANOMALY so với các lần trước, nên nhóm cần kiểm tra lại dữ liệu đầu vào trước khi kết luận.', 'Sự bất thường, dị thường', 'advanced', 1170),
  ('v152', 'antiquated', 'Nhóm vẫn gửi các bảng tính rời rạc qua thư để quản lý dự án, cách làm ANTIQUATED này khiến việc theo dõi tiến độ rất khó khăn.', 'Cổ lỗ sĩ, cũ kỹ', 'advanced', 1220),
  ('v153', 'apprehensive', 'Tôi cảm thấy APPREHENSIVE trước buổi phỏng vấn đầu tiên, vì chưa biết người phỏng vấn sẽ hỏi những câu hỏi gì.', 'E sợ, lo lắng về điều gì đó sắp xảy ra', 'advanced', 1150),
  ('v154', 'arduous', 'Leo lên đỉnh núi trong một ngày là một hành trình ARDUOUS, nhưng khi đứng trên đỉnh và nhìn bình minh thì mọi mệt nhọc đều đáng.', 'Gian nan, cực nhọc', 'advanced', 1200),
  ('v155', 'austere', 'Ông ấy có lối sống AUSTERE, chỉ dùng những đồ dùng cần thiết, không mua sắm thứ gì xa xỉ và tiết kiệm gần như mọi khoản chi.', 'Khắc khổ, giản dị quá mức', 'advanced', 1240),
  ('v156', 'banal', 'Bài phát biểu của diễn giả khá BANAL, toàn những câu nói chung chung nên khán giả không mấy hứng thú theo dõi đến cuối.', 'Tầm thường, vô vị, sáo rỗng', 'advanced', 1180),
  ('v157', 'benevolent', 'Người quản lý cũ rất BENEVOLENT, luôn quan tâm đến sức khỏe và hoàn cảnh của nhân viên, và sẵn sàng giúp đỡ khi có việc gấp.', 'Nhân từ, rộng lượng', 'advanced', 1160),
  ('v158', 'callous', 'Việc thông báo nghỉ việc qua tin nhắn một cách CALLOUS khiến nhiều người trong nhóm buồn và thất vọng về cách công ty đối xử.', 'Vô tâm, nhẫn tâm', 'advanced', 1190),
  ('v159', 'capitulate', 'Sau nhiều ngày thương lượng, bên cung cấp đành CAPITULATE và chấp nhận giảm giá theo đề nghị của chúng tôi.', 'Đầu hàng, chịu khuất phục', 'advanced', 1250),
  ('v160', 'circumvent', 'Để khỏi phải chờ lâu, nhóm tìm cách CIRCUMVENT thủ tục đăng ký dài dòng bằng cách nộp hồ sơ qua cổng trực tuyến của văn phòng.', 'Dùng mưu mẹo để lách luật', 'advanced', 1230)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v161', 'clandestine', 'Hai nhóm bạn có một buổi gặp CLANDESTINE ở quán cà phê vắng, vì muốn giữ bất ngờ cho sinh nhật của người bạn thân.', 'Bí mật, lén lút', 'advanced', 1270),
  ('v162', 'coerce', 'Quản lý không được COERCE nhân viên làm thêm giờ khi họ đã từ chối, vì điều đó đi ngược lại quyền lợi của người lao động.', 'Ép buộc, cưỡng bức', 'advanced', 1210),
  ('v163', 'complacent', 'Dù đã có chứng chỉ, bạn cũng không nên COMPLACENT, vì công nghệ thay đổi nhanh và kiến thức cũ sẽ lỗi thời sau vài năm.', 'Tự mãn, hài lòng với bản thân', 'advanced', 1170),
  ('v164', 'concede', 'Sau khi nghe lập luận rõ ràng, anh ấy đành CONCEDE rằng phương án của tôi hợp lý hơn trong trường hợp này.', 'Thừa nhận (thường là miễn cưỡng)', 'advanced', 1150),
  ('v165', 'condescending', 'Giọng điệu CONDESCENDING khi hướng dẫn người mới khiến ai nghe cũng thấy mình bị coi thường, dù nội dung nói không sai.', 'Ra vẻ bề trên, khinh khỉnh', 'advanced', 1200),
  ('v166', 'convoluted', 'Hướng dẫn tính thuế thu nhập trong tài liệu này khá CONVOLUTED, đọc ba lần mà vẫn chưa hiểu rõ cách tính từng khoản.', 'Phức tạp, rắc rối', 'advanced', 1220),
  ('v167', 'credulous', 'Đừng quá CREDULOUS khi gặp lời hứa việc nhẹ lương cao trên mạng, hãy kiểm tra thông tin công ty và đọc kỹ hợp đồng trước.', 'Cả tin, dễ tin người', 'advanced', 1180),
  ('v168', 'curtail', 'Để tiết kiệm, gia đình quyết định CURTAIL các khoản chi không cần thiết như ăn ngoài thường xuyên và mua sắm trực tuyến.', 'Cắt bớt, rút ngắn', 'advanced', 1190),
  ('v169', 'cynicism', 'Sự CYNICISM của anh ấy với các ứng dụng học ngoại ngữ đến từ việc đã thử rất nhiều nhưng chưa thấy tiến bộ rõ rệt nào.', 'Thái độ hoài nghi, yếm thế', 'advanced', 1160),
  ('v170', 'debilitating', 'Cơn đau đầu DEBILITATING khiến tôi không thể đọc sách hay làm việc suốt buổi chiều, nên phải nghỉ ngơi ở nhà cả ngày.', 'Làm suy yếu, làm kiệt sức', 'advanced', 1240),
  ('v171', 'delineate', 'Bản kế hoạch cần DELINEATE rõ trách nhiệm của từng người, để không ai đùn đẩy công việc cho người khác khi có vấn đề phát sinh.', 'Vạch ra, mô tả chi tiết', 'advanced', 1260),
  ('v172', 'discrepancy', 'Có một DISCREPANCY giữa số tiền ghi trên hóa đơn và số tiền trong sao kê ngân hàng, nên tôi đã gọi hỏi lại bộ phận kế toán.', 'Sự khác nhau, không thống nhất', 'advanced', 1200),
  ('v173', 'dismissive', 'Anh ấy có thái độ DISMISSIVE khi nghe ý kiến của em, chỉ phất tay rồi nói tiếp mà không suy nghĩ thêm về đề xuất đó.', 'Gạt bỏ, coi thường', 'advanced', 1170),
  ('v174', 'disparate', 'Phải gom các nguồn tài liệu DISPARATE gồm sách, bài báo và đoạn phim thành một bài tổng quan hoàn chỉnh cho buổi thuyết trình.', 'Khác hẳn nhau, tạp nham', 'advanced', 1210),
  ('v175', 'draconian', 'Quy định trừ điểm của lớp học này khá DRACONIAN, đi trễ một phút cũng bị trừ điểm nên cả nhóm đều lo lắng khi đến muộn.', 'Hà khắc, khắc nghiệt', 'advanced', 1280),
  ('v176', 'duplicitous', 'Anh ấy có hành vi DUPLICITOUS: trong cuộc họp thì khen dự án, nhưng sau đó lại nói xấu với người khác mà không hề giải thích.', 'Hai mặt, gian trá', 'advanced', 1300),
  ('v177', 'elusive', 'Lỗi này rất ELUSIVE, lúc nào cũng xuất hiện ngẫu nhiên, nên nhóm mất cả buổi chiều chỉ để tái hiện được đúng tình huống gây lỗi.', 'Khó nắm bắt, hay lảng tránh', 'advanced', 1190),
  ('v178', 'emulate', 'Tôi cố gắng EMULATE cách trưởng nhóm giữ bình tĩnh khi họp với khách hàng khó tính, lắng nghe trước rồi mới đưa ra đề xuất.', 'Noi gương, học tập theo', 'advanced', 1160),
  ('v179', 'equivocate', 'Khi được hỏi khi nào sẽ hoàn thành, anh ấy EQUIVOCATE và không trả lời rõ ràng, khiến cả nhóm vẫn chưa biết thời hạn cụ thể.', 'Nói mập mờ, lập lờ để lừa dối', 'advanced', 1290),
  ('v180', 'exorbitant', 'Giá một ly cà phê ở khu du lịch này khá EXORBITANT, gấp ba lần giá ở quán gần nhà, nên tôi quyết định ngồi quán nhỏ hơn.', 'Quá mức, cắt cổ (về giá cả)', 'advanced', 1220),
  ('v181', 'expedient', 'Thấy máy in ở văn phòng bị hỏng, anh Tuấn chọn cách EXPEDIENT là mượn máy của phòng bên cạnh để in gấp tài liệu.', 'Tiện lợi nhất thời, thực dụng', 'advanced', 1230),
  ('v182', 'extraneous', 'Khi làm bài tập nhóm, em nên bỏ những đoạn EXTRANEOUS không liên quan đến chủ đề để bài viết gọn và rõ ràng hơn.', 'Không liên quan, ngoài lề', 'advanced', 1250),
  ('v183', 'fallacious', 'Bạn ấy đưa ra lập luận FALLACIOUS rằng cứ học nhiều là chắc chắn được điểm cao, nên cả nhóm phải tranh luận mãi.', 'Sai lầm, ngụy biện', 'advanced', 1270),
  ('v184', 'fastidious', 'Chị Lan FASTIDIOUS khi chọn quán cà phê, ghế phải sạch, bàn không được dính nước, không thì chị nhất định không ngồi.', 'Khó tính, cầu kỳ thái quá', 'advanced', 1240),
  ('v185', 'fervent', 'Cô giáo dạy văn rất FERVENT với việc đọc sách, thường khuyên cả lớp mỗi tối đọc ít nhất hai mươi trang.', 'Nồng nhiệt, tha thiết', 'advanced', 1180),
  ('v186', 'flagrant', 'Đăng lại ảnh của người khác mà không ghi nguồn là một hành vi FLAGRANT, ai nhìn vào cũng thấy rõ là vi phạm.', 'Trắng trợn, lộ liễu', 'advanced', 1210),
  ('v187', 'fleeting', 'Khoảnh khắc FLEETING khi cả nhà cùng ngồi ăn cơm tối làm mẹ thấy mọi mệt mỏi trong ngày bỗng tan biến.', 'Thoáng qua, phù du', 'advanced', 1130),
  ('v188', 'forthright', 'Trong buổi phỏng vấn, anh ấy trả lời FORTHRIGHT rằng mình chưa biết dùng Excel và sẽ tự học thêm trong vài tháng.', 'Thẳng thắn, bộc trực', 'advanced', 1160),
  ('v189', 'frugal', 'Sau khi ra trường, Minh sống rất FRUGAL: nấu cơm ở nhà, đi xe buýt và để dành tiền mua một chiếc laptop mới.', 'Tiết kiệm, thanh đạm', 'advanced', 1140),
  ('v190', 'futile', 'Dù đã gọi điện nhiều lần, việc đòi lại tiền cọc phòng trọ vẫn FUTILE vì chủ nhà không chịu nghe máy.', 'Vô ích, không kết quả', 'advanced', 1170),
  ('v191', 'gratuitous', 'Phần giới thiệu app có quá nhiều hiệu ứng GRATUITOUS, không giúp người dùng hiểu thêm gì nên em bỏ qua luôn.', 'Vô lý, không cần thiết', 'advanced', 1260),
  ('v192', 'hegemony', 'Quán cà phê chuỗi này có HEGEMONY ở khu trung tâm thành phố, gần như quán nào cũng phải cạnh tranh với họ.', 'Sự bá quyền, thống trị', 'advanced', 1300),
  ('v193', 'hubris', 'Anh ấy tự tin quá mức, cho rằng không cần đọc lại bản thiết kế, và chính HUBRIS đó khiến cả nhóm làm lại từ đầu.', 'Sự ngạo mạn quá mức', 'advanced', 1280),
  ('v194', 'hypocritical', 'Thầy dặn cả lớp không dùng điện thoại trong giờ học, nhưng chính thầy lại nhắn tin suốt buổi, thật HYPOCRITICAL.', 'Đạo đức giả', 'advanced', 1190),
  ('v195', 'idealistic', 'Bạn Hà muốn mở quán sách mà không vay vốn nào, ai cũng bảo ý tưởng đó IDEALISTIC, nhưng Hà vẫn lập kế hoạch kỹ.', 'Lý tưởng hóa, xa rời thực tế', 'advanced', 1150),
  ('v196', 'inadvertent', 'Trong lúc dọn máy, em xóa mất file báo cáo một cách INADVERTENT, may mà hôm qua em đã sao lưu lên đám mây.', 'Vô ý, không chủ tâm', 'advanced', 1230),
  ('v197', 'incongruent', 'Cách ăn mặc quá sang của anh ấy INCONGRUENT với không khí buổi họp lớp, nên mọi người nhìn anh hơi lạ.', 'Không phù hợp, mâu thuẫn', 'advanced', 1260),
  ('v198', 'indolent', 'Cậu em trai rất INDOLENT, cuối tuần chỉ nằm trên ghế xem phim, quên luôn việc rửa bát giúp mẹ.', 'Lười biếng, nhác làm', 'advanced', 1200),
  ('v199', 'inexorable', 'Điện thoại thông minh ngày càng phổ biến là một xu hướng INEXORABLE, đến ông bà ở quê cũng đã biết dùng app chuyển tiền.', 'Không thể lay chuyển/ngăn cản', 'advanced', 1310),
  ('v200', 'insidious', 'Thói quen lướt mạng xã hội trước khi ngủ là một tác hại INSIDIOUS: lúc đầu chỉ vài phút, lâu dần thì mất cả tiếng.', 'Âm thầm nguy hại', 'advanced', 1270)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v201', 'intransigent', 'Ông chủ nhà rất INTRANSIGENT về tiền cọc, không chịu giảm dù chỉ một trăm nghìn, nên hai bên bàn mãi vẫn chưa xong.', 'Cố chấp, không nhượng bộ', 'advanced', 1290),
  ('v202', 'irrevocable', 'Sau khi bấm nút chuyển tiền, giao dịch trở thành IRREVOCABLE, nên bạn nhớ kiểm tra lại số tài khoản trước khi xác nhận.', 'Không thể thu hồi/thay đổi', 'advanced', 1300),
  ('v203', 'lamentable', 'Kết quả kiểm tra giữa kỳ của cả lớp thật LAMENTABLE, hơn nửa số bạn chưa đạt điểm trung bình môn.', 'Đáng buồn, đáng tiếc', 'advanced', 1220),
  ('v204', 'lethargic', 'Sau một đêm ngủ không đủ giấc, sáng nay em thấy người LETHARGIC, cứ ngồi nhìn màn hình mà chẳng làm được gì.', 'Uể oải, lờ đờ', 'advanced', 1180),
  ('v205', 'lucid', 'Bạn Nam giải thích cách làm bài toán rất LUCID, từng bước rõ ràng nên cả lớp hiểu ngay trong mười phút.', 'Sáng suốt, rõ ràng', 'advanced', 1140),
  ('v206', 'magnanimous', 'Sau khi bạn làm mất bản tài liệu chung, chị Hoa vẫn MAGNANIMOUS, không trách móc gì và giúp bạn làm lại từ đầu.', 'Hào hiệp, cao thượng', 'advanced', 1250),
  ('v207', 'malleable', 'Các bạn sinh viên năm nhất thường còn MALLEABLE, dễ tiếp thu góp ý và thay đổi cách học khi được hướng dẫn tốt.', 'Dễ bị tác động, dễ uốn nắn', 'advanced', 1210),
  ('v208', 'mendacious', 'Tin nhắn quảng cáo kia MENDACIOUS khi hứa giảm chín mươi phần trăm, nhưng lúc thanh toán thì giá vẫn y nguyên.', 'Sai sự thật, giả dối', 'advanced', 1320),
  ('v209', 'melancholy', 'Trời mưa cả buổi chiều, ngồi bên cửa sổ nghe nhạc, em thấy lòng MELANCHOLY một cách khó tả.', 'U sầu, buồn bã', 'advanced', 1160),
  ('v210', 'mollify', 'Thấy em trai giận vì bị giành mất đồ chơi, mẹ phải kể chuyện và đưa kẹo để MOLLIFY con.', 'Làm nguôi đi, xoa dịu', 'advanced', 1130),
  ('v211', 'mercurial', 'Tính khí của cô bạn cùng phòng rất MERCURIAL: sáng vui vẻ, chiều đã im lặng và chẳng nói gì với ai.', 'Thất thường, hay thay đổi', 'advanced', 1110),
  ('v212', 'nefarious', 'Trong truyện, lão phù thủy có một kế hoạch NEFARIOUS nhằm chiếm lấy ngôi làng, cả nhóm đọc mà hồi hộp theo.', 'Hung ác, bất chính', 'advanced', 1310),
  ('v213', 'nonchalant', 'Biết mình trượt bài kiểm tra, bạn tôi vẫn NONCHALANT, chỉ cười rồi rủ đi ăn bánh tráng trộn.', 'Thờ ơ, lãnh đạm', 'advanced', 1190),
  ('v214', 'nostalgic', 'Lật lại cuốn album ảnh hồi cấp ba, mẹ thấy NOSTALGIC và kể cho cả nhà nghe những kỷ niệm ngày xưa.', 'Hoài niệm', 'advanced', 1130),
  ('v215', 'oblivious', 'Bạn ấy OBLIVIOUS trước việc cả nhóm đã đổi lịch họp, nên đến phòng đúng giờ cũ rồi chờ mãi.', 'Vô tâm, không nhận thấy', 'advanced', 1160),
  ('v216', 'ominous', 'Tin nhắn từ sếp chỉ có một dòng Mai gặp tôi, nhưng đọc lên nghe thật OMINOUS khiến ai cũng hồi hộp.', 'Điềm xấu, đáng lo ngại', 'advanced', 1180),
  ('v217', 'opaque', 'Cách tính điểm của môn học này khá OPAQUE, sinh viên không biết chính xác phần nào được bao nhiêu điểm.', 'Mập mờ, không minh bạch', 'advanced', 1200),
  ('v218', 'ostentatious', 'Cô bạn vừa đi du lịch về khoe ảnh với bộ đồ hàng hiệu OSTENTATIOUS, khiến nhiều người trong nhóm chỉ mỉm cười.', 'Phô trương, khoe mẽ', 'advanced', 1300),
  ('v219', 'pedantic', 'Thầy hướng dẫn luận văn khá PEDANTIC, chỉ cần một dấu phẩy sai là thầy yêu cầu sửa lại cả trang.', 'Câu nệ, soi xét tiểu tiết', 'advanced', 1250),
  ('v220', 'perfidious', 'Trong truyện lịch sử, người bạn thân nhất của vua lại có hành động PERFIDIOUS, bí mật bán đứng cả đoàn quân.', 'Phản bội, xảo trá', 'advanced', 1330),
  ('v221', 'pertinent', 'Trong buổi họp lớp, câu hỏi của bạn Linh rất PERTINENT, đi thẳng vào vấn đề lịch thi cuối kỳ của cả lớp.', 'Đúng trọng tâm, liên quan trực tiếp', 'advanced', 1150),
  ('v222', 'phlegmatic', 'Anh trai tôi PHLEGMATIC lắm, dù xe hỏng giữa đường cũng chỉ thở dài rồi gọi xe ôm đi tiếp.', 'Điềm tĩnh, lạnh lùng', 'advanced', 1280),
  ('v223', 'placid', 'Mặt hồ buổi sáng sớm PLACID, nước phẳng lặng, rất thích hợp để ngồi đọc sách và uống trà.', 'Điềm tĩnh, lặng lẽ', 'advanced', 1200),
  ('v224', 'polarizing', 'Chủ đề chọn đồ ăn cho buổi liên hoan rất POLARIZING, người thích cay, người lại kiên quyết không ăn cay.', 'Gây chia rẽ, phân cực', 'advanced', 1170),
  ('v225', 'pompous', 'Vị khách mời trong buổi hội thảo nói chuyện rất POMPOUS, toàn những câu nghe kêu nhưng không có ví dụ cụ thể.', 'Hợm hĩnh, vênh váo', 'advanced', 1220),
  ('v226', 'punctilious', 'Chị kế toán trong công ty rất PUNCTILIOUS, khoản chi nào cũng phải có hóa đơn và chữ ký đầy đủ mới chịu duyệt.', 'Kỹ lưỡng, câu nệ nghi thức', 'advanced', 1280),
  ('v227', 'precarious', 'Sau khi công ty thu hẹp quy mô, công việc của nhiều người trở nên PRECARIOUS, không ai chắc tháng sau còn làm không.', 'Bấp bênh, nguy hiểm', 'advanced', 1190),
  ('v228', 'presumptuous', 'Mới vào nhóm mà bạn đã đề nghị đổi cả kiến trúc dự án thì hơi PRESUMPTUOUS, mọi người cần thời gian tìm hiểu trước.', 'Tự phụ, quá trớn', 'advanced', 1260),
  ('v229', 'pretentious', 'Quán cà phê đó PRETENTIOUS quá, tên món nào cũng dài dằng dặc nhưng ly cà phê thì nhạt thếch.', 'Giả tạo, tự cao tự đại', 'advanced', 1230),
  ('v230', 'pugnacious', 'Trong nhóm chat, bạn Đức rất PUGNACIOUS, ai không đồng ý là bạn ấy tranh luận đến tận khuya.', 'Hay gây gổ, hiếu chiến', 'advanced', 1260),
  ('v231', 'abnegation', 'Mẹ tôi đã sống với tinh thần ABNEGATION suốt nhiều năm, luôn nhường phần ngon cho con và tiết kiệm cho gia đình.', 'Sự hy sinh, từ bỏ quyền lợi', 'expert', 1380),
  ('v232', 'abstemious', 'Để giữ sức khỏe, anh Huy ABSTEMIOUS trong ăn uống, ít đường, không uống nước ngọt và chỉ uống một ly cà phê buổi sáng.', 'Tiết chế, điều độ (ăn uống)', 'expert', 1420),
  ('v233', 'acerbic', 'Lời nhận xét ACERBIC của thầy làm cả lớp im lặng, nhưng ai cũng thấy đúng là bài viết còn nhiều lỗi.', 'Chua cay, gay gắt', 'expert', 1390),
  ('v234', 'acumen', 'Chị Thu có ACUMEN trong việc chọn đồ, nhìn qua là biết món nào sẽ bán chạy ở chợ đêm cuối tuần.', 'Sự nhạy bén, sắc sảo', 'expert', 1400),
  ('v235', 'adumbrate', 'Trong buổi khởi động dự án, sếp chỉ ADUMBRATE sơ qua về định hướng chung, còn chi tiết thì sẽ bàn sau.', 'Phác thảo, ám chỉ sơ lược', 'expert', 1470),
  ('v236', 'anachronism', 'Dùng đầu máy đĩa CD để nghe nhạc ở thời nay đúng là một ANACHRONISM, nhưng bố tôi vẫn thích thế.', 'Sự lỗi thời, sai thời đại', 'expert', 1440),
  ('v237', 'anathema', 'Với người làm việc tự do như chị, việc phải chấm công đúng từng phút là một ANATHEMA, chị không thể chịu nổi.', 'Điều cực kỳ ghét bỏ', 'expert', 1460),
  ('v238', 'apocryphal', 'Câu chuyện về thần đồng biết làm web từ năm lên sáu tuổi nghe rất APOCRYPHAL, chưa ai kiểm chứng được.', 'Không xác thực, bị bịa đặt', 'expert', 1450),
  ('v239', 'apotheosis', 'Buổi biểu diễn cuối năm là APOTHEOSIS của cả quá trình tập luyện, khán giả vỗ tay không ngớt.', 'Đỉnh cao, sự thần thánh hóa', 'expert', 1490),
  ('v240', 'approbation', 'Sau khi trình bày kế hoạch, nhóm nhận được sự APPROBATION của giáo viên hướng dẫn và được tiến hành.', 'Sự tán thành, chấp thuận', 'expert', 1430)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v241', 'arcane', 'Các ký hiệu trong sách toán này ARCANE đến mức em đọc cả buổi mà chưa hiểu nổi một trang nào.', 'Bí ẩn, kỳ bí, khó hiểu', 'expert', 1380),
  ('v242', 'arrant', 'Câu chuyện ông ấy kể về việc tự học trong một tuần đúng là chuyện bịa ARRANT, không ai tin nổi.', 'Hoàn toàn, hết sức (nghĩa xấu)', 'expert', 1460),
  ('v243', 'artifice', 'Quảng cáo kem dưỡng da này chỉ là một ARTIFICE: ảnh đã chỉnh sửa rất nhiều nên trông khác hẳn thực tế.', 'Mưu mẹo, sự đánh tráo giả tạo', 'expert', 1420),
  ('v244', 'ascetic', 'Anh bạn tôi sống ASCETIC khi chuẩn bị thi chứng chỉ, không xem phim, không đi chơi, chỉ học và ngủ đúng giờ.', 'Khổ hạnh, tu hành', 'expert', 1440),
  ('v245', 'assiduous', 'Bạn Hương ASSIDUOUS trong việc học tiếng Anh, tối nào cũng dành một tiếng luyện nghe và viết.', 'Cần cù, siêng năng', 'expert', 1390),
  ('v246', 'atavistic', 'Thấy con mèo nhỏ chạy vụt qua, anh ấy có phản ứng ATAVISTIC là đuổi theo ngay, dù chẳng biết để làm gì.', 'Mang tính bản năng nguyên thủy', 'expert', 1480),
  ('v247', 'attenuate', 'Uống đủ nước và nghỉ ngơi hợp lý sẽ giúp ATTENUATE mệt mỏi sau những ngày học căng thẳng liên tục.', 'Làm yếu đi, giảm cường độ', 'expert', 1410),
  ('v248', 'august', 'Phòng hội nghị có một hàng ghế AUGUST dành cho các diễn giả, trông rất trang trọng và nghiêm túc.', 'Uy nghi, đáng kính', 'expert', 1370),
  ('v249', 'avarice', 'Hắn ta chỉ nghĩ đến lợi nhuận riêng mà không quan tâm ai, sự AVARICE đó khiến nhiều người phải thiệt thòi.', 'Lòng tham tiền bạc', 'expert', 1430),
  ('v250', 'bellicose', 'Hôm nay anh trai tôi BELLICOSE quá, ai nhắc đến chuyện điểm số cũng bị cãi lại ngay lập tức.', 'Hiếu chiến, thích gây hấn', 'expert', 1400),
  ('v251', 'byzantine', 'Thủ tục đăng ký tạm trú ở phường này BYZANTINE quá, phải qua năm bước với bảy loại giấy tờ mới xong.', 'Rắc rối, cực kỳ phức tạp', 'expert', 1470),
  ('v252', 'capricious', 'Khách hàng này CAPRICIOUS lắm, sáng chốt mẫu thiết kế này, chiều đã đổi sang mẫu khác hoàn toàn.', 'Thất thường, hay thay đổi', 'expert', 1390),
  ('v253', 'castigate', 'Trong buổi họp, trưởng nhóm CASTIGATE việc nộp báo cáo trễ, khiến cả nhóm im lặng suốt cả buổi.', 'Chỉ trích dữ dội', 'expert', 1450),
  ('v254', 'caustic', 'Bình luận CAUSTIC dưới bài đăng của bạn làm cả nhóm chat im bặt, không ai biết nên trả lời thế nào.', 'Cay nghiệt, châm chọc', 'expert', 1410),
  ('v255', 'chicanery', 'Người bán hàng dùng nhiều CHICANERY để khách tưởng là đang được giảm giá, nhưng thực ra giá vẫn như cũ.', 'Mánh khóe, thủ thuật lừa dối', 'expert', 1480),
  ('v256', 'churlish', 'Không trả lời tin nhắn công việc của bạn bè dù đã đọc là hành động CHURLISH, nhất là khi họ đang cần giúp đỡ.', 'Thô lỗ, mất lịch sự', 'expert', 1380),
  ('v257', 'circumlocution', 'Thay vì nói thẳng là bài đã nộp trễ, bạn ấy dùng CIRCUMLOCUTION nên thầy phải hỏi lại tới ba lần.', 'Cách nói vòng vo, dài dòng', 'expert', 1490),
  ('v258', 'clairvoyant', 'Anh bạn đoán tỉ số trận bóng đá lần nào cũng đúng, nhiều người gọi anh là người CLAIRVOYANT.', 'Sáng suốt, có khả năng tiên đoán', 'expert', 1420),
  ('v259', 'cloying', 'Ly trà sữa này CLOYING quá, uống vài ngụm là thấy ngấy, đúng là không hợp với em chút nào.', 'Ngọt xớt, giả tạo đến phát ngấy', 'expert', 1360),
  ('v260', 'cogent', 'Bài thuyết trình của Minh rất COGENT, có số liệu rõ ràng và lập luận chặt chẽ nên cô giáo cho điểm cao.', 'Vững chắc, có sức thuyết phục', 'expert', 1380),
  ('v261', 'compunction', 'Cô ấy nói dối để được đi chơi mà không hề có COMPUNCTION, cũng chẳng thấy áy náy chút nào.', 'Sự hối hận, cắn rứt lương tâm', 'expert', 1430),
  ('v262', 'conflagration', 'Cuộc tranh cãi trong nhóm chat hôm qua đúng là một CONFLAGRATION, cả bọn cãi nhau từ tối đến khuya.', 'Đám cháy lớn, sự xung đột dữ dội', 'expert', 1460),
  ('v263', 'consternation', 'Khi cô giáo thông báo dời lịch thi sang tuần sau, cả lớp nhìn nhau với vẻ CONSTERNATION vì chưa kịp ôn bài.', 'Sự kinh hoàng, tiệt vọng', 'expert', 1460),
  ('v264', 'craven', 'Anh ấy CRAVEN khi bị hỏi về lỗi của mình, lại đổ hết trách nhiệm cho bạn đồng đội đang vắng mặt.', 'Hèn nhát', 'expert', 1400),
  ('v265', 'contrite', 'Cậu em trai CONTRITE xin lỗi mẹ vì đã làm vỡ chiếc bình hoa, đôi mắt vẫn đỏ hoe.', 'Ăn năn, hối lỗi', 'expert', 1370),
  ('v266', 'convivial', 'Buổi họp mặt lớp cũ diễn ra rất CONVIVIAL, ai cũng kể chuyện vui và hát karaoke đến khuya mới chịu về.', 'Vui vẻ, thân thiện', 'expert', 1360),
  ('v267', 'copious', 'Bạn Mai ghi chú COPIOUS trong buổi học, mỗi slide đều có vài dòng tóm tắt nên ôn thi rất nhanh.', 'Dồi dào, phong phú', 'expert', 1370),
  ('v268', 'cupidity', 'Chính lòng CUPIDITY muốn làm giàu nhanh đã khiến nhiều người đầu tư mù quáng vào những thứ không rõ ràng.', 'Lòng tham (đặc biệt là tiền bạc)', 'expert', 1450),
  ('v269', 'dearth', 'Mùa tuyển sinh này có một DEARTH chỗ trọ gần trường, sinh viên phải đi xa hơn mà vẫn khó tìm được phòng.', 'Sự khan hiếm, thiếu thốn', 'expert', 1390),
  ('v270', 'deference', 'Khi nói chuyện với các cô chú lớn tuổi, em luôn giữ thái độ DEFERENCE, lắng nghe và không ngắt lời ai.', 'Sự tôn trọng, cung kính', 'expert', 1400),
  ('v271', 'deleterious', 'Thức khuya làm việc liên tục mà không vận động có thể DELETERIOUS đến sức khỏe và cột sống về lâu dài.', 'Gây hại, có tác động xấu', 'expert', 1440),
  ('v272', 'denouement', 'Cuốn tiểu thuyết có nhiều tình tiết rối rắm, nhưng phần DENOUEMENT ở cuối truyện lại rất rõ ràng và thuyết phục.', 'Kết cục, hạ màn', 'expert', 1460),
  ('v273', 'desultory', 'Anh ấy học tiếng Anh một cách DESULTORY, hôm nay đọc vài trang, tuần sau lại bỏ hẳn nên chưa tiến bộ được bao nhiêu.', 'Rời rạc, thiếu hệ thống', 'expert', 1470),
  ('v274', 'inveterate', 'Bà tôi là người INVETERATE thích đi chợ sớm, dù sức khỏe không còn tốt, ngày nào bà cũng dậy từ năm giờ sáng.', 'Thâm căn cố đế, khó bỏ', 'expert', 1410),
  ('v275', 'lachrymose', 'Bộ phim cũ ấy có giọng điệu LACHRYMOSE, cảnh nào cũng đẫm nước mắt nên xem xong tôi thấy khá mệt.', 'Hay khóc, ủy mị, gây xúc động mạnh', 'expert', 1450),
  ('v276', 'lambaste', 'Nhiều người dùng LAMBASTE nhà phát hành trên mạng xã hội vì bản cập nhật mới làm mất hết dữ liệu đã lưu.', 'Chỉ trích gay gắt', 'expert', 1420),
  ('v277', 'languid', 'Buổi chiều hè oi bức, ai nấy trong văn phòng đều LANGUID, mắt díu lại và chỉ muốn nghỉ ngơi một chút.', 'Uể oải, lờ đờ', 'expert', 1380),
  ('v278', 'loquacious', 'Bác bán hàng rất LOQUACIOUS, hỏi một câu thì bác kể tận nửa tiếng về chuyện gia đình và giá rau ngoài chợ.', 'Nói nhiều, huyên thuyên', 'expert', 1390),
  ('v279', 'machiavellian', 'Trong cuốn tiểu thuyết công sở, nhân vật chính là một kẻ MACHIAVELLIAN, luôn tính toán từng bước để đạt quyền lực.', 'Xảo quyệt, mưu mô chính trị', 'expert', 1490),
  ('v280', 'magniloquent', 'Anh bạn vừa khởi nghiệp nói chuyện rất MAGNILOQUENT về kế hoạch thay đổi cả ngành, nghe hoành tráng nhưng chưa có sản phẩm nào.', 'Nói khoác lác, khoa trương', 'expert', 1480)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v281', 'maladroit', 'Anh ấy khá MALADROIT trong giao tiếp, nên khi cần xin lỗi khách hàng lại nói làm mọi chuyện rối thêm.', 'Vụng về, thiếu khéo léo', 'expert', 1420),
  ('v282', 'malaise', 'Sau nhiều tháng làm việc liên tục, cô ấy cảm thấy một MALAISE khó gọi tên, không hẳn buồn nhưng cũng chẳng vui.', 'Sự khó chịu, bất an mơ hồ', 'expert', 1400),
  ('v283', 'meretricious', 'Trang bìa của cuốn sách trông rất MERETRICIOUS, đầy màu mè và kim tuyến, nhưng nội dung bên trong thì khá rỗng.', 'Hào nhoáng nhưng vô giá trị', 'expert', 1470),
  ('v284', 'mettlesome', 'Cậu ấy là người METTLESOME, dù thi trượt hai lần vẫn đăng ký ôn lại và không hề nản chí.', 'Dũng cảm, đầy nghị lực', 'expert', 1440),
  ('v285', 'misanthropic', 'Nhân vật trong truyện là người MISANTHROPIC, suốt ngày khép cửa và tránh gặp gỡ bạn bè dù ai cũng muốn giúp.', 'Ghét người, lánh đời', 'expert', 1460),
  ('v286', 'mnemonic', 'Cô giáo dạy chúng tôi một MNEMONIC để nhớ thứ tự các hành tinh, mỗi chữ cái đầu ghép lại thành một câu dễ nhớ.', 'Thuật ghi nhớ', 'expert', 1380),
  ('v287', 'mordant', 'Bài báo viết theo giọng MORDANT, đọc khá vui nhưng nhiều câu châm biếm rất sắc, khiến người bị nhắc đến thấy khó chịu.', 'Châm chọc, cay nghiệt', 'expert', 1430),
  ('v288', 'munificent', 'Quỹ học bổng của trường rất MUNIFICENT, mỗi năm hỗ trợ học phí và sinh hoạt cho hàng trăm sinh viên có hoàn cảnh khó khăn.', 'Hào phóng, cực kỳ rộng rãi', 'expert', 1410),
  ('v289', 'nebulous', 'Kế hoạch của nhóm vẫn còn NEBULOUS, chưa ai nắm rõ mục tiêu cuối cùng cũng như thời gian hoàn thành.', 'Mơ hồ, mù mờ', 'expert', 1390),
  ('v290', 'noisome', 'Tủ lạnh bỏ quên thức ăn cả tuần khiến cả căn bếp có mùi NOISOME, cả nhà phải mở cửa sổ và dọn ngay.', 'Hôi thối, khó chịu kinh khủng', 'expert', 1420),
  ('v291', 'obdurate', 'Ông ấy OBDURATE không chịu nghe góp ý, dù mọi người đã đưa ra nhiều bằng chứng rõ ràng về vấn đề này.', 'Cứng đầu, ngoan cố', 'expert', 1440),
  ('v292', 'obstreperous', 'Mấy đứa trẻ OBSTREPEROUS chạy nhảy la hét khắp hành lang, cô giáo phải nhắc nhiều lần mới chịu im lặng.', 'Ồn ào bướng bỉnh, khó kiểm soát', 'expert', 1470),
  ('v293', 'obtuse', 'Anh ấy hơi OBTUSE khi gặp những câu nói ẩn ý, nên lúc nào cũng phải giải thích thêm mới hiểu được.', 'Chậm hiểu, đần độn', 'expert', 1380),
  ('v294', 'officious', 'Bác bảo vệ tỏ ra OFFICIOUS, cứ hỏi han từng người ra vào và bắt ghi sổ dù quy định không yêu cầu như vậy.', 'Hay lanh chanh, thích can thiệp chuyện người khác', 'expert', 1410),
  ('v295', 'oleaginous', 'Nhân viên mới có giọng điệu OLEAGINOUS khi nói chuyện với sếp, khen không ngớt nhưng ai cũng thấy hơi giả tạo.', 'Nịnh bợ, bóng bẩy (nghĩa bóng)', 'expert', 1490),
  ('v296', 'onerous', 'Việc chăm sóc hai đứa nhỏ và đi làm cùng lúc thật ONEROUS, nên cô ấy cần có người giúp đỡ vào cuối tuần.', 'Nặng nề, khó nhọc', 'expert', 1370),
  ('v297', 'opprobrium', 'Quyết định sai lầm của công ty khiến họ phải hứng chịu OPPROBRIUM mạnh mẽ từ khách hàng trên nhiều diễn đàn.', 'Sự chỉ trích dữ dội, vết nhục', 'expert', 1460),
  ('v298', 'parsimonious', 'Ông chủ tiệm khá PARSIMONIOUS trong chuyện chi tiêu, nên ít khi nâng cấp máy móc dù doanh thu vẫn tốt.', 'Bủn xỉn, cực kỳ keo kiệt', 'expert', 1430),
  ('v299', 'pejorative', 'Khi học từ vựng, bạn nên chú ý những từ mang nghĩa PEJORATIVE, tức là có sắc thái chê bai hoặc coi thường.', 'Mang nghĩa xấu, có tính miệt thị', 'expert', 1420),
  ('v300', 'penurious', 'Sau khi đóng học phí, cậu sinh viên sống trong hoàn cảnh PENURIOUS, phải nấu mì gói cả tuần để tiết kiệm.', 'Nghèo túng, thiếu thốn tột cùng', 'expert', 1450),
  ('v301', 'perspective', 'Đọc thêm sách về lịch sử giúp tôi có một PERSPECTIVE rộng hơn khi nhìn nhận các vấn đề trong cuộc sống.', 'Góc nhìn, quan điểm', 'intermediate', 920),
  ('v302', 'ambitious', 'Kế hoạch học tiếng Anh trong sáu tháng của cô ấy khá AMBITIOUS, nhưng cô vẫn quyết tâm học mỗi ngày một giờ.', 'Tham vọng', 'beginner', 850),
  ('v303', 'collaborate', 'Để nộp báo cáo đúng hạn, nhóm của chúng tôi phải COLLABORATE chặt chẽ, chia việc rõ ràng và cùng kiểm tra từng phần.', 'Hợp tác, cộng tác', 'beginner', 880),
  ('v304', 'adaptable', 'Sinh viên quốc tế thường phải ADAPTABLE với môi trường mới, từ bữa ăn hằng ngày đến cách học và cách giao tiếp.', 'Dễ thích nghi', 'intermediate', 940),
  ('v305', 'consistent', 'Muốn tiến bộ khi học tiếng Anh, bạn cần CONSISTENT, mỗi ngày học một chút thay vì học dồn rồi nghỉ cả tuần.', 'Nhất quán, kiên trì', 'intermediate', 910),
  ('v306', 'obtain', 'Sau hai tháng chờ đợi, anh ấy đã OBTAIN được giấy phép làm việc và có thể bắt đầu công việc mới ở thành phố khác.', 'Đạt được, giành được', 'intermediate', 960),
  ('v307', 'specific', 'Khi viết thư xin việc, bạn nên nêu SPECIFIC những kỹ năng và kinh nghiệm liên quan trực tiếp đến vị trí ứng tuyển.', 'Cụ thể, rõ ràng', 'beginner', 830),
  ('v308', 'valuable', 'Kinh nghiệm thực tập một năm là một tài sản VALUABLE, giúp tôi hiểu rõ môi trường làm việc trước khi ra trường.', 'Quý giá, có giá trị', 'beginner', 840),
  ('v309', 'estimate', 'Trước khi đặt hàng, hãy ESTIMATE chi phí vận chuyển và thuế để biết tổng số tiền mình phải trả là bao nhiêu.', 'Ước tính', 'beginner', 880),
  ('v310', 'typical', 'Ăn sáng bằng bánh mì và cà phê sữa là thói quen TYPICAL của nhiều người Sài Gòn, nhất là vào buổi sáng đi làm.', 'Điển hình, đặc trưng', 'beginner', 820),
  ('v311', 'versatile', 'Chiếc máy tính xách tay này khá VERSATILE, vừa dùng để học, vừa chỉnh sửa ảnh và xem phim đều ổn định.', 'Linh hoạt, đa năng', 'intermediate', 1050),
  ('v312', 'sufficient', 'Với mức lương hiện tại, khoản tiết kiệm này vẫn SUFFICIENT để trang trải chi phí sinh hoạt trong ba tháng.', 'Đầy đủ, đủ dùng', 'intermediate', 940),
  ('v313', 'priority', 'Với sinh viên năm cuối, việc hoàn thành khóa luận phải là PRIORITY, các hoạt động khác có thể để sau.', 'Sự ưu tiên', 'beginner', 850),
  ('v314', 'approach', 'Thay vì học thuộc lòng, tôi thử một APPROACH khác là luyện nói qua những tình huống thật trong đời sống hằng ngày.', 'Cách tiếp cận, phương pháp', 'intermediate', 920),
  ('v315', 'convince', 'Tôi mất gần một tiếng để CONVINCE bố mẹ đồng ý cho tôi học thêm khóa lập trình vào cuối tuần.', 'Thuyết phục', 'beginner', 870),
  ('v316', 'procedure', 'Trước khi vận hành máy, nhân viên phải làm đúng PROCEDURE an toàn đã được hướng dẫn trong sổ tay sử dụng.', 'Quy trình, thủ tục', 'intermediate', 950),
  ('v317', 'significance', 'Bạn có hiểu SIGNIFICANCE của việc sao lưu dữ liệu trước khi cập nhật phần mềm không? Đây là việc rất quan trọng.', 'Tầm quan trọng, ý nghĩa', 'intermediate', 1020),
  ('v318', 'reveal', 'Trong buổi họp lớp, cô ấy quyết định REVEAL kết quả học bổng vừa nhận được sau nhiều tháng chờ đợi.', 'Tiết lộ, hé lộ', 'beginner', 830),
  ('v319', 'challenging', 'Dự án lập trình đầu tiên của nhóm khá CHALLENGING, vì phải học công nghệ mới trong thời gian rất ngắn.', 'Đầy thách thức', 'beginner', 890),
  ('v320', 'acquire', 'Qua ba năm làm việc ở công ty logistics, anh ấy ACQUIRE được kỹ năng quản lý kho và đàm phán với nhà cung cấp.', 'Có được, thu nhận được', 'intermediate', 960)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v321', 'beneficial', 'Ngủ đủ giấc và ăn nhiều rau củ rất BENEFICIAL cho làn da, nhất là khi phải ngồi trước máy tính nhiều giờ.', 'Có lợi', 'beginner', 850),
  ('v322', 'capable', 'Cô ấy là một trưởng nhóm CAPABLE, biết phân công công việc hợp lý và giữ tiến độ dự án luôn ổn định.', 'Có khả năng, năng lực', 'beginner', 870),
  ('v323', 'contradict', 'Thông tin trong bài viết CONTRADICT với số liệu chính thức, nên bạn nên kiểm tra lại nguồn trước khi chia sẻ.', 'Mâu thuẫn, trái ngược', 'intermediate', 980),
  ('v324', 'distinct', 'Hai loại cà phê này có hương vị DISTINCT, một bên đậm đắng còn bên kia có vị chua thanh của trái cây.', 'Khác biệt rõ ràng', 'intermediate', 910),
  ('v325', 'eliminate', 'Để ELIMINATE lỗi chính tả trong bài luận, bạn nên đọc lại to từng câu và dùng thêm công cụ kiểm tra.', 'Loại bỏ, triệt tiêu', 'intermediate', 930),
  ('v326', 'generalize', 'Bạn không nên GENERALIZE từ vài trải nghiệm cá nhân để kết luận về cả một nhóm người hay một thành phố.', 'Khái quát hóa, đánh đồng', 'intermediate', 950),
  ('v327', 'hinder', 'Tiếng ồn từ công trường bên cạnh HINDER việc học của sinh viên, nên thư viện phải chuyển lên tầng trên.', 'Cản trở, kìm hãm', 'intermediate', 970),
  ('v328', 'implement', 'Nhóm kỹ thuật đã IMPLEMENT tính năng đăng nhập bằng vân tay trong bản cập nhật của tuần này.', 'Triển khai, thực hiện', 'intermediate', 920),
  ('v329', 'inadequate', 'Hệ thống thông gió trong phòng học hiện nay còn INADEQUATE, nên lớp học khá ngột ngạt vào buổi chiều.', 'Thiếu hụt, không thỏa đáng', 'intermediate', 990),
  ('v330', 'maintain', 'Để MAINTAIN sức khỏe khi làm việc văn phòng, anh ấy đi bộ ba mươi phút mỗi ngày và uống đủ nước.', 'Duy trì, bảo trì', 'beginner', 860),
  ('v331', 'notable', 'Điều NOTABLE nhất trong buổi triển lãm là các bức tranh do học sinh cấp ba thực hiện, rất có hồn.', 'Đáng chú ý, nổi bật', 'beginner', 890),
  ('v332', 'optimistic', 'Dù kỳ thi khó, cô bạn vẫn OPTIMISTIC và tin rằng mình sẽ đạt điểm cao như mong muốn của gia đình.', 'Lạc quan', 'beginner', 840),
  ('v333', 'partial', 'Đây mới chỉ là bản PARTIAL của báo cáo, phần số liệu cuối cùng sẽ được bổ sung vào tuần sau.', 'Một phần, thiên vị', 'beginner', 830),
  ('v334', 'practical', 'Thay vì học lý thuyết dài dòng, bạn nên chọn một khóa học PRACTICAL có nhiều bài tập và tình huống thực tế.', 'Thực tế, thực tiễn', 'beginner', 870),
  ('v335', 'quickly', 'Nhà hàng phục vụ rất QUICKLY, chỉ sau năm phút là tô bún bò đã được mang lên bàn cho chúng tôi.', 'Nhanh chóng', 'beginner', 800),
  ('v336', 'reaction', 'REACTION của khán giả sau buổi biểu diễn rất tích cực, nhiều người đứng dậy vỗ tay kéo dài.', 'Phản ứng', 'beginner', 820),
  ('v337', 'skepticism', 'Khi đọc quảng cáo giảm giá chín mươi phần trăm, tôi nhìn nó với chút SKEPTICISM và kiểm tra giá gốc trước khi mua.', 'Sự hoài nghi', 'intermediate', 1040),
  ('v338', 'tendency', 'Trẻ em có TENDENCY bắt chước hành vi của người lớn, nên cha mẹ cần làm gương trong sinh hoạt hằng ngày.', 'Xu hướng, khuynh hướng', 'intermediate', 910),
  ('v339', 'unexpected', 'Một tin nhắn UNEXPECTED từ người bạn cũ khiến cô ấy vui cả buổi chiều, sau nhiều năm không liên lạc.', 'Bất ngờ, không mong đợi', 'beginner', 850),
  ('v340', 'validate', 'Trước khi gửi bản thảo, bạn nên nhờ thầy cô VALIDATE lại số liệu và cách trích dẫn trong bài viết.', 'Xác nhận, phê chuẩn', 'intermediate', 940),
  ('v341', 'worthwhile', 'Dù phải dậy sớm để học thêm kỹ năng thuyết trình, tôi thấy công sức đó rất WORTHWHILE khi được nhận giải.', 'Đáng công, xứng đáng', 'intermediate', 900),
  ('v342', 'yield', 'Khoản tiết kiệm gửi ngân hàng YIELD lãi suất ổn định mỗi tháng, phù hợp cho người mới bắt đầu tích lũy.', 'Mang lại, sản sinh ra, nhượng bộ', 'intermediate', 1020),
  ('v343', 'abandon', 'Dù gặp nhiều khó khăn khi học lập trình, cậu ấy không ABANDON dự án cá nhân và vẫn cập nhật mã nguồn mỗi tuần.', 'Từ bỏ, bỏ rơi', 'beginner', 880),
  ('v344', 'brief', 'Trước buổi họp sáng mai, anh ấy gửi cho cả nhóm một BRIEF ngắn gọn về số liệu bán hàng trong quý này.', 'Ngắn gọn, tóm tắt', 'beginner', 830),
  ('v345', 'certain', 'Tôi CERTAIN rằng lịch học sẽ thay đổi vào tuần sau, nên hãy kiểm tra lại thông báo trên trang của trường.', 'Chắc chắn', 'beginner', 810),
  ('v346', 'decline', 'Anh ấy lịch sự DECLINE lời mời dự tiệc vì phải chuẩn bị bài thuyết trình cho ngày hôm sau.', 'Từ chối, suy giảm', 'intermediate', 940),
  ('v347', 'accommodate', 'Phòng họp mới của công ty đủ rộng để ACCOMMODATE khoảng ba mươi người tham dự buổi đào tạo nội bộ.', 'Đáp ứng, cung cấp chỗ ở', 'intermediate', 960),
  ('v348', 'deliberate', 'Cô ấy đưa ra quyết định một cách DELIBERATE, cân nhắc kỹ từng lựa chọn trước khi ký hợp đồng thuê nhà.', 'Cố ý, thận trọng', 'intermediate', 980),
  ('v349', 'financial', 'Trước khi vay tiền mua xe, bạn nên xem xét kỹ tình hình FINANCIAL của gia đình và khả năng trả nợ hằng tháng.', 'Thuộc về tài chính', 'beginner', 840),
  ('v350', 'generous', 'Chị ấy GENEROUS chia sẻ bữa cơm với hàng xóm, nên cả khu phố đều quý mến và thường ghé nhà chơi.', 'Hào phóng, rộng lượng', 'beginner', 835),
  ('v351', 'immediate', 'Nếu thấy triệu chứng bất thường, bạn nên liên hệ phòng khám để được tư vấn IMMEDIATE thay vì chờ đợi.', 'Ngay lập tức', 'beginner', 845),
  ('v352', 'knowledgeable', 'Người hướng dẫn tour rất KNOWLEDGEABLE về lịch sử phố cổ, giới thiệu từng ngôi nhà với nhiều câu chuyện thú vị.', 'Am hiểu, có kiến thức rộng', 'intermediate', 950),
  ('v353', 'motivate', 'Mục tiêu nhỏ mỗi tuần giúp tôi MOTIVATE bản thân học tiếng Anh đều đặn, vì nhìn thấy tiến bộ của mình mỗi tuần khiến người ta vui.', 'Thúc đẩy, tạo động lực', 'beginner', 860),
  ('v354', 'negative', 'Đừng để những bình luận NEGATIVE trên mạng làm bạn mất tự tin, hãy tập trung vào điều bạn đã làm được.', 'Tiêu cực', 'beginner', 810),
  ('v355', 'quality', 'Chiếc áo khoác này có QUALITY tốt, vải dày và đường may chắc chắn, giá lại hợp lý so với mặt bằng chung.', 'Chất lượng', 'beginner', 805),
  ('v356', 'reasonable', 'Giá phòng trọ ở khu này khá REASONABLE, nằm gần trường và có chỗ để xe, nên nhiều sinh viên chọn thuê.', 'Hợp lý, phải chăng', 'beginner', 855),
  ('v357', 'ultimate', 'Mục tiêu ULTIMATE của tôi là làm việc ở một công ty quốc tế, nhưng trước mắt phải tích lũy đủ kinh nghiệm.', 'Cuối cùng, tối thượng', 'intermediate', 940),
  ('v358', 'vague', 'Hướng dẫn trong email khá VAGUE, không nói rõ hạn nộp bài và cách nộp, nên tôi phải hỏi lại cô giáo.', 'Mơ hồ, mập mờ', 'intermediate', 910),
  ('v359', 'dependable', 'Anh Minh là đồng nghiệp DEPENDABLE, việc đã nhận thì luôn hoàn thành đúng hạn và báo trước nếu có vấn đề.', 'Đáng tin cậy', 'intermediate', 930),
  ('v360', 'effective', 'Pha một cốc nước ấm với mật ong là cách EFFECTIVE để dịu cổ họng khi phải nói nhiều trong ngày.', 'Hiệu quả', 'beginner', 850)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v361', 'appropriate', 'Trước khi đi phỏng vấn, chị hỏi bạn xem bộ đồ này có APPROPRIATE cho môi trường công sở không.', 'Phù hợp, thích hợp', 'intermediate', 960),
  ('v362', 'behave', 'Khi đến thăm gia đình bạn gái, anh nên BEHAVE lịch sự, nói năng nhẹ nhàng và giữ phép tắc.', 'Cư xử, ăn ở', 'beginner', 820),
  ('v363', 'coincidence', 'Hai người cùng học một trường đại học, cùng sinh vào tháng 5 và cùng thích bóng đá, đúng là một COINCIDENCE thú vị.', 'Sự trùng hợp ngẫu nhiên', 'intermediate', 980),
  ('v364', 'determined', 'Sau lần thi trượt đầu tiên, Lan DETERMINED học thêm mỗi tối để đạt điểm cao trong kỳ thi tiếp theo.', 'Quyết tâm, kiên quyết', 'beginner', 880),
  ('v365', 'encourage', 'Khi em muốn học vẽ, cô giáo luôn ENCOURAGE em luyện tập mỗi ngày và góp ý nhẹ nhàng khi cần.', 'Khuyến khích, động viên', 'beginner', 860),
  ('v366', 'familiar', 'Vừa bước vào thư viện, em thấy mùi giấy cũ rất FAMILIAR, giống như những buổi chiều học bài ở trường cũ.', 'Quen thuộc', 'beginner', 810),
  ('v367', 'hinder', 'Tiếng ồn từ công trường bên cạnh HINDER việc học của tôi, nên tôi phải chuyển sang học ở thư viện.', 'Cản trở, kìm hãm', 'intermediate', 970),
  ('v368', 'imitate', 'Trong lớp luyện phát âm, nhiều bạn thường IMITATE giọng của giáo viên để nói tiếng Anh chuẩn hơn.', 'Bắt chước, nhại lại', 'intermediate', 940),
  ('v369', 'jealous', 'Thấy bạn thân được thăng chức, Minh có chút JEALOUS, nhưng anh vẫn chúc mừng bạn một cách chân thành.', 'Ghen tị, ghen tuông', 'beginner', 830),
  ('v370', 'limit', 'Thẻ tín dụng của tôi có LIMIT một triệu đồng mỗi tháng, nên tôi luôn cố gắng kiểm soát chi tiêu.', 'Giới hạn, hạn mức', 'beginner', 815),
  ('v371', 'notice', 'Mãi đến khi ra khỏi quán, tôi mới NOTICE là mình quên mang theo ví ở bàn ăn.', 'Để ý thấy, nhận ra', 'beginner', 810),
  ('v372', 'patient', 'Cô giáo rất PATIENT khi giải thích lại bài toán cho cả lớp, dù có em hỏi đi hỏi lại nhiều lần.', 'Kiên nhẫn', 'beginner', 825),
  ('v373', 'quarrel', 'Hai anh em QUARREL về việc ai sẽ rửa chén tối nay, cuối cùng cả hai đều phải làm chung.', 'Cãi vã, tranh chấp', 'intermediate', 930),
  ('v374', 'stubborn', 'Dù bác sĩ đã khuyên nhiều lần, bác vẫn STUBBORN không chịu đi khám sức khỏe định kỳ.', 'Bướng bỉnh, lỳ lợm', 'beginner', 860),
  ('v375', 'temporary', 'Vì sửa nhà nên cả gia đình chuyển sang ở nhà bà ngoại trong một thời gian TEMPORARY.', 'Tạm thời', 'beginner', 870),
  ('v376', 'urgent', 'Sếp gửi tin nhắn báo có việc URGENT cần xử lý trước 9 giờ sáng, nên tôi phải đến văn phòng sớm.', 'Khẩn cấp', 'beginner', 845),
  ('v377', 'willing', 'Nếu bạn cần giúp chuyển nhà, tôi rất WILLING đến sớm để khiêng đồ và dọn dẹp cùng bạn.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v378', 'accurate', 'Trước khi nộp báo cáo, nhóm cần kiểm tra lại số liệu để chắc chắn thông tin ACCURATE và đầy đủ.', 'Chính xác', 'beginner', 880),
  ('v379', 'believable', 'Lý do bạn đưa ra để xin nghỉ học nghe không BELIEVABLE lắm, giáo viên có thể sẽ hỏi thêm.', 'Có thể tin được', 'beginner', 815),
  ('v380', 'convenient', 'Ứng dụng đặt đồ ăn này rất CONVENIENT vì tôi chỉ cần vài bước là có thể thanh toán và theo dõi đơn hàng.', 'Tiện lợi', 'beginner', 820),
  ('v381', 'dependable', 'Trong nhóm đi phượt, Hải là người DEPENDABLE nhất vì lúc nào anh cũng đúng giờ và lo chu đáo mọi việc.', 'Đáng tin cậy', 'intermediate', 930),
  ('v382', 'effective', 'Học từ vựng bằng thẻ ghi nhớ mỗi ngày là phương pháp EFFECTIVE, nhất là khi bạn ôn lại đều đặn.', 'Hiệu quả', 'beginner', 850),
  ('v383', 'grateful', 'Tôi rất GRATEFUL khi cô giáo dành thời gian chấm lại bài giúp tôi, cảm ơn cô rất nhiều.', 'Biết ơn', 'beginner', 860),
  ('v384', 'honest', 'Bạn có thể HONEST cho tôi biết ý kiến về bản thuyết trình này không? Góp ý thẳng thắn sẽ giúp tôi tiến bộ.', 'Thành thật, chân thật', 'beginner', 810),
  ('v385', 'ignore', 'Khi có người bình luận tiêu cực trên mạng, bạn nên IGNORE và tập trung vào việc học của mình.', 'Phớt lờ, lờ đi', 'beginner', 820),
  ('v386', 'intention', 'Tôi hiểu INTENTION của anh là muốn giúp cả nhóm, nhưng cách chia việc hôm nay còn chưa hợp lý.', 'Ý định, mục đích', 'intermediate', 910),
  ('v387', 'manage', 'Với lịch học dày đặc, Thảo phải MANAGE thời gian thật khéo để vừa đi làm thêm vừa ôn thi.', 'Quản lý, xoay xở', 'beginner', 850),
  ('v388', 'necessary', 'Trước khi đi du lịch, bạn nên chuẩn bị một số giấy tờ NECESSARY như hộ chiếu, vé máy bay và bảo hiểm.', 'Cần thiết', 'beginner', 840),
  ('v389', 'optimistic', 'Dù kết quả thi chưa như mong đợi, em vẫn OPTIMISTIC và tin rằng mình sẽ tiến bộ trong kỳ tới.', 'Lạc quan', 'beginner', 840),
  ('v390', 'partial', 'Báo cáo này mới chỉ là một PARTIAL kết quả, nhóm sẽ cập nhật đầy đủ số liệu vào tuần sau.', 'Một phần, thiên vị', 'beginner', 830),
  ('v391', 'significant', 'Sau ba tháng tập thể dục đều đặn, Nam thấy có SIGNIFICANT thay đổi về sức khỏe và giấc ngủ của mình.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v392', 'tolerate', 'Anh ấy không thể TOLERATE việc đồng nghiệp đến họp trễ, nên luôn nhắc mọi người đến đúng giờ.', 'Chịu đựng, tha thứ', 'beginner', 855),
  ('v393', 'utilize', 'Trong buổi học nhóm, chúng tôi UTILIZE máy chiếu và bảng trắng để trình bày ý tưởng một cách rõ ràng.', 'Sử dụng, tận dụng', 'beginner', 860),
  ('v394', 'valid', 'Vé của bạn chỉ VALID đến hết ngày mai, nhớ kiểm tra lại thời hạn trước khi đến rạp chiếu phim.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v395', 'wonder', 'Tôi WONDER không biết lớp học thêm có đổi lịch không, vì trong nhóm chưa thấy thông báo nào.', 'Tự hỏi, băn khoăn', 'beginner', 810),
  ('v396', 'admit', 'Sau một hồi suy nghĩ, anh ấy ADMIT là mình đã quên gửi email xác nhận cho khách hàng.', 'Thừa nhận, nhận vào', 'beginner', 865),
  ('v397', 'boring', 'Buổi họp kéo dài hơn hai tiếng mà chưa chốt được việc gì, làm ai cũng thấy BORING và mệt mỏi.', 'Buồn chán, tẻ nhạt', 'beginner', 800),
  ('v398', 'complain', 'Khách hàng COMPLAIN về việc giao hàng chậm, nên nhân viên đã xin lỗi và gửi thêm mã giảm giá.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v399', 'doubt', 'Tôi DOUBT cửa hàng này bán hàng chính hãng, vì giá quá thấp so với mặt bằng chung của thị trường.', 'Nghi ngờ', 'beginner', 855),
  ('v400', 'eager', 'Các bạn sinh viên rất EAGER tham gia buổi trải nghiệm nghề nghiệp, ai cũng hỏi về kỹ năng phỏng vấn.', 'Háo hức, hăm hở', 'intermediate', 920)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v401', 'force', 'Cô không nên FORCE con học thêm nhiều môn cùng lúc, con cần thời gian để nghỉ ngơi và chơi với bạn.', 'Ép buộc, lực lượng', 'beginner', 840),
  ('v402', 'gather', 'Cuối tuần này, cả lớp sẽ GATHER ở công viên để chụp ảnh kỷ niệm trước kỳ thi cuối kỳ.', 'Tập hợp, thu thập', 'beginner', 830),
  ('v403', 'hardly', 'Dạo này làm việc nhiều, tôi HARDLY có thời gian gọi về nhà, nên thấy rất áy náy với gia đình.', 'Hầu như không', 'beginner', 815),
  ('v404', 'imagine', 'Bạn có thể IMAGINE cảnh biển xanh và bãi cát trắng trong kỳ nghỉ hè sắp tới không?', 'Tưởng tượng', 'beginner', 805),
  ('v405', 'kindness', 'Một lời cảm ơn và chút KINDNESS của người lạ đã khiến ngày làm việc của tôi nhẹ nhàng hơn nhiều.', 'Sự tử tế, lòng tốt', 'beginner', 820),
  ('v406', 'loose', 'Sau khi giảm cân, chiếc quần jeans này trở nên LOOSE, tôi phải nhờ thợ may chỉnh lại phần eo.', 'Lỏng lẻo, rộng', 'beginner', 835),
  ('v407', 'mention', 'Trong buổi họp, anh ấy chỉ MENTION sơ qua về kế hoạch quý tới chứ chưa đi vào chi tiết.', 'Đề cập đến', 'beginner', 840),
  ('v408', 'offer', 'Công ty vừa OFFER cho em vị trí nhân viên marketing, em đang cân nhắc giữa mức lương và lộ trình thăng tiến.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v409', 'particular', 'Bạn có yêu cầu PARTICULAR nào về màu sắc hay kích cỡ khi đặt bánh sinh nhật không?', 'Cụ thể, đặc biệt', 'intermediate', 910),
  ('v410', 'qualify', 'Để QUALIFY cho chương trình học bổng, em cần đạt chứng chỉ tiếng Anh và có điểm trung bình trên 8.', 'Đủ điều kiện, tư cách', 'intermediate', 940),
  ('v411', 'struggle', 'Lúc mới chuyển sang học lập trình, tôi STRUGGLE rất nhiều với các khái niệm trừu tượng nhưng vẫn kiên trì học.', 'Vật lộn, đấu tranh', 'beginner', 880),
  ('v412', 'thorough', 'Trước khi thuê phòng trọ, bạn nên kiểm tra THOROUGH hệ thống điện nước và cửa sổ để tránh phát sinh chi phí.', 'Kỹ lưỡng, thấu đáo', 'intermediate', 960),
  ('v413', 'unique', 'Quán cà phê này có không gian UNIQUE, tường được trang trí bằng những bức tranh do các họa sĩ trẻ vẽ.', 'Độc nhất, độc đáo', 'beginner', 860),
  ('v414', 'whisper', 'Trong thư viện, mọi người thường WHISPER với nhau để không làm phiền những người đang đọc sách.', 'Thì thầm', 'beginner', 830),
  ('v415', 'annoying', 'Những cuộc gọi quảng cáo vào giữa trưa thật sự ANNOYING, nên tôi đã bật chế độ chặn số lạ trên điện thoại.', 'Làm phiền, khó chịu', 'beginner', 820),
  ('v416', 'believe', 'Tôi không thể BELIEVE được là bạn đã đậu học bổng toàn phần, chúc mừng bạn nhiều nhé.', 'Tin tưởng', 'beginner', 800),
  ('v417', 'critical', 'Trong dự án phần mềm này, bước kiểm thử cuối cùng là CRITICAL, vì nếu bỏ qua thì lỗi sẽ xuất hiện khi khách dùng.', 'Quan trọng, nguy cấp, phê bình', 'intermediate', 970),
  ('v418', 'delighted', 'Mẹ tôi rất DELIGHTED khi nhận được bó hoa tôi tặng nhân ngày 8/3, dù mẹ vẫn nhắc tôi đừng tiêu tiền nhiều.', 'Vui mừng, hài lòng', 'beginner', 890),
  ('v419', 'frustrated', 'Sau nhiều lần cài đặt mà vẫn không được, Hùng cảm thấy FRUSTRATED và quyết định nhờ bạn giúp.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v420', 'influence', 'Thầy giáo có INFLUENCE lớn đến cách tôi học tập và suy nghĩ, đến giờ tôi vẫn nhớ những lời thầy dạy.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v421', 'judge', 'Trước khi JUDGE một người qua lần gặp đầu tiên, bạn nên tìm hiểu thêm và lắng nghe kỹ hơn.', 'Đánh giá, phán xét', 'beginner', 830),
  ('v422', 'knowledge', 'Ông Hùng chia sẻ KNOWLEDGE về nghề thiết kế cho các bạn trẻ trong câu lạc bộ mỗi tuần.', 'Kiến thức, sự hiểu biết', 'beginner', 840),
  ('v423', 'lack', 'Phòng học này LACK ánh sáng tự nhiên, nên sinh viên thường phải bật đèn ngay cả giữa ban ngày.', 'Thiếu hụt', 'beginner', 810),
  ('v424', 'maintain', 'Để MAINTAIN thói quen tập thể dục, tôi đặt báo thức sớm vào các buổi sáng thứ hai, thứ tư và thứ sáu.', 'Duy trì, giữ vững', 'beginner', 865),
  ('v425', 'nervous', 'Trước buổi phỏng vấn, Linh cảm thấy NERVOUS nên đã luyện trả lời câu hỏi trước gương nhiều lần.', 'Lo lắng, hồi hộp', 'beginner', 815),
  ('v426', 'opportunity', 'Chương trình trao đổi sinh viên này là một OPPORTUNITY tốt để em làm quen với môi trường học tập quốc tế.', 'Cơ hội', 'beginner', 850),
  ('v427', 'prefer', 'Tôi PREFER học buổi sáng vì đầu óc tỉnh táo hơn, còn buổi tối thường thấy mệt và khó tập trung.', 'Thích hơn', 'beginner', 820),
  ('v428', 'quality', 'Khi mua giày chạy bộ, bạn nên ưu tiên QUALITY hơn giá rẻ, vì đế giày tốt sẽ bảo vệ chân khi tập luyện.', 'Chất lượng, đặc tính', 'beginner', 805),
  ('v429', 'recognize', 'Sau nhiều năm không gặp, tôi suýt không RECOGNIZE được người bạn cũ vì anh ấy đã thay đổi kiểu tóc.', 'Nhận ra, công nhận', 'beginner', 875),
  ('v430', 'sensitive', 'Chủ đề lương thưởng khá SENSITIVE trong công ty, nên bạn hãy cân nhắc khi nói chuyện trong nhóm.', 'Nhạy cảm', 'intermediate', 935),
  ('v431', 'trustworthy', 'Anh Long là người TRUSTWORTHY, nên cả nhóm đều chọn anh giữ quỹ chung cho chuyến đi.', 'Đáng tin cậy', 'intermediate', 925),
  ('v432', 'urgent', 'Bạn cùng phòng nhắn tin URGENT hỏi tôi có mang chìa khóa không, vì cô ấy đang đứng ngoài cửa.', 'Khẩn cấp', 'beginner', 845),
  ('v433', 'valuable', 'Thời gian là tài sản VALUABLE nhất của sinh viên, nên hãy lên kế hoạch để không lãng phí nó vào việc vô ích.', 'Quý giá', 'beginner', 855),
  ('v434', 'particular', 'Mẹ tôi có PARTICULAR thích món canh chua nấu với cá, nên mỗi lần về quê tôi đều xin mẹ nấu món này.', 'Cụ thể, đặc biệt', 'intermediate', 910),
  ('v435', 'qualify', 'Để QUALIFY làm việc tại chi nhánh Tokyo, anh cần đạt chứng chỉ tiếng Nhật và có kinh nghiệm ba năm.', 'Đủ điều kiện, đủ tư cách', 'intermediate', 940),
  ('v436', 'reasonable', 'Giá phòng ở khu này khá REASONABLE so với mặt bằng chung, lại gần trường nên sinh viên rất thích.', 'Hợp lý, giá cả phải chăng', 'beginner', 855),
  ('v437', 'struggle', 'Mới chuyển đến thành phố lớn, tôi STRUGGLE tìm được nhà trọ vừa rẻ vừa gần chỗ làm.', 'Vật lộn, đấu tranh', 'beginner', 880),
  ('v438', 'thorough', 'Trước khi thuê xe máy, bạn nên kiểm tra THOROUGH phanh, đèn và lốp xe để đảm bảo an toàn cho chuyến đi.', 'Kỹ lưỡng, thấu đáo', 'intermediate', 960),
  ('v439', 'unique', 'Chiếc bình gốm này có hoa văn UNIQUE vì do người thợ làng nghề tạo nên tay, không có cái nào giống cái nào.', 'Độc nhất, độc đáo', 'beginner', 860),
  ('v440', 'whisper', 'Trong buổi lễ tốt nghiệp, mấy bạn ngồi hàng sau WHISPER với nhau khi thầy hiệu trưởng đang phát biểu.', 'Thì thầm', 'beginner', 830)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v441', 'annoying', 'Tiếng thông báo liên tục từ nhóm chat lớp thật sự ANNOYING khi tôi đang cố ngủ trưa.', 'Làm phiền, khó chịu', 'beginner', 820),
  ('v442', 'believe', 'Cô bạn cùng lớp không thể BELIEVE điểm số của mình sau kỳ thi giữa kỳ, vì cô đã học rất chăm chỉ.', 'Tin tưởng', 'beginner', 800),
  ('v443', 'critical', 'Trong buổi kiểm tra chất lượng, nhóm chúng tôi xem điểm CRITICAL của sản phẩm trước khi quyết định ra mắt.', 'Quan trọng, nguy cấp, phê bình', 'intermediate', 970),
  ('v444', 'delighted', 'Cả nhà rất DELIGHTED khi cô con gái được nhận vào đội tuyển của trường, ai cũng gọi điện chúc mừng.', 'Vui mừng, hài lòng', 'beginner', 890),
  ('v445', 'frustrated', 'Cảm giác FRUSTRATED thật khó chịu khi thanh toán đơn hàng mà app ngân hàng cứ báo lỗi nhiều lần.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v446', 'genuine', 'Cô ấy là người GENUINE, luôn lắng nghe và nói lời cảm ơn thật lòng khi bạn giúp đỡ mình.', 'Thật lòng, chân thành', 'beginner', 880),
  ('v447', 'hesitate', 'Nếu bạn cần giúp đỡ về bài tập, đừng HESITATE mà hãy hỏi tôi bất cứ lúc nào nhé.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v448', 'influence', 'Phong cách học tập của nhóm chúng tôi chịu INFLUENCE rõ rệt từ các video hướng dẫn trên YouTube.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v449', 'urgent', 'Trường gửi thông báo URGENT yêu cầu sinh viên nộp lại hồ sơ đăng ký trước 5 giờ chiều nay.', 'Khẩn cấp', 'beginner', 845),
  ('v450', 'valuable', 'Mỗi lần học nhóm, bạn ấy thường chia sẻ ghi chú VALUABLE giúp cả lớp hiểu bài nhanh hơn.', 'Quý giá, có giá trị', 'beginner', 855),
  ('v451', 'appropriate', 'Trước khi đi dự đám cưới, Lan hỏi bạn xem bộ đồ này có APPROPRIATE không, hay nên chọn áo sơ mi lịch sự hơn.', 'Phù hợp, thích hợp', 'intermediate', 960),
  ('v452', 'behave', 'Lần đầu gặp bố mẹ người yêu, Minh tự nhắc mình phải BEHAVE lịch sự và nói năng nhẹ nhàng.', 'Cư xử, ăn ở', 'beginner', 820),
  ('v453', 'coincidence', 'Hôm nay mình gặp lại cô bạn cũ ở sân bay, đúng là một COINCIDENCE vì cả hai đều bay cùng một chuyến.', 'Sự trùng hợp ngẫu nhiên', 'intermediate', 980),
  ('v454', 'determined', 'Sau khi thi trượt một lần, An rất DETERMINED ôn lại từng chương và đặt mục tiêu đậu vào năm sau.', 'Quyết tâm, kiên quyết', 'beginner', 880),
  ('v455', 'encourage', 'Cô giáo luôn ENCOURAGE học sinh nói tiếng Anh dù còn mắc lỗi, vì như vậy các em sẽ tự tin hơn.', 'Khuyến khích, động viên', 'beginner', 860),
  ('v456', 'familiar', 'Vừa bước vào quán cà phê nhỏ ở góc phố, Hương thấy không khí rất FAMILIAR như thể đã đến đây nhiều lần.', 'Quen thuộc', 'beginner', 810),
  ('v457', 'generous', 'Chú chủ quán phở hôm nay rất GENEROUS, cho thêm một tô thịt bò mà không tính thêm tiền.', 'Hào phóng, rộng lượng', 'beginner', 835),
  ('v458', 'hesitate', 'Khi cô nhân viên hỏi có muốn thêm bánh không, tôi HESITATE một lúc rồi mới gật đầu.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v459', 'imitate', 'Bé An rất thích IMITATE cách bố nói chuyện điện thoại, cả nhà nghe xong đều bật cười.', 'Bắt chước, nhại lại', 'intermediate', 940),
  ('v460', 'jealous', 'Thấy bạn thân được thăng chức, Hải cảm thấy hơi JEALOUS nhưng vẫn chúc mừng bạn thật lòng.', 'Ghen tị, ghen tuông', 'beginner', 830),
  ('v461', 'knowledgeable', 'Ông Tuấn rất KNOWLEDGEABLE về lịch sử nên buổi hướng dẫn tham quan bảo tàng rất thú vị.', 'Am hiểu, có kiến thức rộng', 'intermediate', 950),
  ('v462', 'limit', 'Ứng dụng ngân hàng có LIMIT số tiền chuyển khoản mỗi ngày, nên bạn nên kiểm tra trước khi thanh toán.', 'Giới hạn', 'beginner', 815),
  ('v463', 'motivate', 'Mục tiêu chạy bộ 5 km vào cuối tháng MOTIVATE Linh đi tập đều đặn mỗi sáng.', 'Thúc đẩy, tạo động lực', 'beginner', 860),
  ('v464', 'notice', 'Khi đi ngang qua công viên, Nam NOTICE một chú chó con đang run rẩy bên bờ hồ.', 'Để ý thấy, nhận ra', 'beginner', 810),
  ('v465', 'obvious', 'Bài toán này khá OBVIOUS: nếu nhân hai vế với 2 thì bạn sẽ thấy đáp án ngay.', 'Rõ ràng, hiển nhiên', 'beginner', 815),
  ('v466', 'patient', 'Dạy con đi xe đạp đòi hỏi bố mẹ phải PATIENT, vì con sẽ ngã nhiều lần trước khi làm được.', 'Kiên nhẫn', 'beginner', 825),
  ('v467', 'quarrel', 'Hai anh em trong nhà thường QUARREL về chuyện ai được dùng máy tính trước, nhưng tối đến lại làm hòa.', 'Cãi vã, tranh chấp', 'intermediate', 930),
  ('v468', 'reasonable', 'Giá vé xem phim ở rạp này khá REASONABLE so với mặt bằng chung, nên nhóm bạn quyết định đi thử.', 'Hợp lý, phải chăng', 'beginner', 855),
  ('v469', 'stubborn', 'Bà nội rất STUBBORN, dù con cháu khuyên thế nào bà cũng nhất định làm theo ý mình.', 'Bướng bỉnh, lỳ lợm', 'beginner', 860),
  ('v470', 'temporary', 'Vì phòng chính đang sửa điện, văn phòng đặt một bàn TEMPORARY gần cửa sổ cho nhân viên làm việc.', 'Tạm thời', 'beginner', 870),
  ('v471', 'urgent', 'Đồng nghiệp gửi email URGENT lúc 8 giờ tối nhờ kiểm tra lại bảng số liệu trước sáng mai.', 'Khẩn cấp', 'beginner', 845),
  ('v472', 'vague', 'Hướng dẫn trong sách về cách cài đặt phần mềm khá VAGUE, nên tôi phải tìm thêm video để làm theo.', 'Mơ hồ, không rõ ràng', 'intermediate', 910),
  ('v473', 'willing', 'Chị Mai rất WILLING giúp các bạn trẻ chỉnh sửa CV, và chị luôn trả lời tin nhắn rất nhanh.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v474', 'accurate', 'Trước khi nộp báo cáo, Hà kiểm tra lại từng con số để chắc rằng mọi thông tin đều ACCURATE.', 'Chính xác', 'beginner', 880),
  ('v475', 'believable', 'Câu chuyện bạn quên ví ở nhà nghe không BELIEVABLE lắm, nên tôi muốn xem lại hóa đơn.', 'Có thể tin được', 'beginner', 815),
  ('v476', 'convenient', 'Ứng dụng đặt xe này rất CONVENIENT vì chỉ cần vài bước là có xe đến đón trước cổng nhà.', 'Tiện lợi', 'beginner', 820),
  ('v477', 'dependable', 'Anh Hùng là người DEPENDABLE trong nhóm dự án, lúc nào cũng hoàn thành việc đúng hạn.', 'Đáng tin cậy', 'intermediate', 930),
  ('v478', 'effective', 'Chia nhỏ bài tập thành từng phần là cách EFFECTIVE để học nhanh và nhớ lâu hơn.', 'Hiệu quả', 'beginner', 850),
  ('v479', 'grateful', 'Cảm ơn bạn đã đến giúp tôi chuyển nhà, tôi rất GRATEFUL vì bạn đã dành cả buổi sáng cuối tuần.', 'Biết ơn', 'beginner', 860),
  ('v480', 'honest', 'Khi bạn hỏi ý kiến về bài thuyết trình, tôi sẽ HONEST nói rằng phần mở đầu còn hơi dài.', 'Thành thật', 'beginner', 810)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v481', 'ignore', 'Khi có người bình luận tiêu cực dưới bài đăng, tốt nhất bạn nên IGNORE và tập trung vào nội dung của mình.', 'Phớt lờ, lờ đi', 'beginner', 820),
  ('v482', 'intention', 'Dù INTENTION của bạn là tốt, nhưng việc tự ý đổi lịch họp đã khiến cả nhóm bị động.', 'Ý định, mục đích', 'intermediate', 910),
  ('v483', 'manage', 'Sinh viên năm nhất phải MANAGE thời gian giữa việc học, làm thêm và sinh hoạt câu lạc bộ.', 'Quản lý, xoay xở', 'beginner', 850),
  ('v484', 'necessary', 'Trước chuyến đi biển, cả nhà kiểm tra danh sách đồ dùng NECESSARY như kem chống nắng và thuốc cảm.', 'Cần thiết', 'beginner', 840),
  ('v485', 'optimistic', 'Dù kết quả đầu tiên chưa tốt, Thảo vẫn OPTIMISTIC rằng dự án sẽ thành công trong vài tháng tới.', 'Lạc quan', 'beginner', 840),
  ('v486', 'partial', 'Bản tóm tắt này chỉ là PARTIAL nội dung của cuộc họp, bạn cần đọc thêm biên bản đầy đủ.', 'Một phần, thiên vị', 'beginner', 830),
  ('v487', 'quickly', 'Nếu cần giấy tờ gấp, bộ phận hành chính có thể in và gửi lại QUICKLY trong buổi sáng.', 'Nhanh chóng', 'beginner', 800),
  ('v488', 'reaction', 'REACTION của khách hàng khi nhận được món quà rất vui, ai cũng khen thiết kế đẹp và tinh tế.', 'Phản ứng', 'beginner', 820),
  ('v489', 'significant', 'Việc giảm 10% chi phí vận hành là một thay đổi SIGNIFICANT đối với một công ty nhỏ như chúng tôi.', 'Quan trọng, đáng kể', 'beginner', 850),
  ('v490', 'tolerate', 'Nhà trọ này không TOLERATE tiếng ồn sau 10 giờ đêm, nên mọi người cần giữ yên lặng.', 'Chịu đựng, tha thứ', 'beginner', 855),
  ('v491', 'utilize', 'Thư viện mở thêm khu tự học, sinh viên có thể UTILIZE không gian này để ôn thi theo nhóm.', 'Tận dụng, sử dụng', 'beginner', 860),
  ('v492', 'valid', 'Vé của bạn chỉ VALID trong vòng 30 ngày kể từ ngày mua, nên hãy sử dụng trước hạn.', 'Hợp lệ, có cơ sở', 'beginner', 840),
  ('v493', 'wonder', 'Sau buổi phỏng vấn, tôi WONDER không biết mình có được chọn hay không.', 'Tự hỏi, băn khoăn', 'beginner', 810),
  ('v494', 'admit', 'Sau khi xem lại video, Khoa phải ADMIT rằng mình đã nói sai thông tin trong buổi thuyết trình.', 'Thừa nhận', 'beginner', 865),
  ('v495', 'boring', 'Buổi học thêm kéo dài ba tiếng mà chỉ đọc slide nên ai cũng thấy BORING.', 'Buồn chán', 'beginner', 800),
  ('v496', 'complain', 'Nếu món ăn nguội, bạn có thể COMPLAIN với nhân viên phục vụ để họ đổi món mới.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v497', 'doubt', 'Tôi DOUBT cuộc họp sáng mai sẽ kết thúc đúng giờ vì còn nhiều việc chưa chốt.', 'Nghi ngờ', 'beginner', 855),
  ('v498', 'eager', 'Các em nhỏ EAGER chờ đến giờ ra chơi để xuống sân đá cầu cùng nhau.', 'Háo hức, hăm hở', 'intermediate', 920),
  ('v499', 'force', 'Anh trai tôi không muốn đi khám răng, và mẹ không thể FORCE anh ấy đi nếu anh không đồng ý.', 'Ép buộc', 'beginner', 840),
  ('v500', 'gather', 'Cuối tuần này cả lớp sẽ GATHER ở quán cà phê gần trường để chúc mừng sinh nhật cô giáo.', 'Tụ họp, tập hợp', 'beginner', 830),
  ('v501', 'hardly', 'Từ khi có con nhỏ, Hoa HARDLY có thời gian đi chợ, nên cả tuần đều đặt đồ ăn online.', 'Hầu như không', 'beginner', 815),
  ('v502', 'imagine', 'Bạn có thể IMAGINE cảnh cả lớp học ngoài trời dưới bóng cây trong buổi sáng mùa thu không?', 'Tưởng tượng', 'beginner', 805),
  ('v503', 'kindness', 'Một cái gật đầu chào buổi sáng hay một lời cảm ơn nhỏ cũng là KINDNESS đáng quý giữa mọi người.', 'Lòng tốt, sự tử tế', 'beginner', 820),
  ('v504', 'loose', 'Dây giày của con bị LOOSE nên dễ vấp, bố hãy buộc lại giúp con trước khi đi học.', 'Lỏng, lỏng lẻo', 'beginner', 835),
  ('v505', 'mention', 'Trong buổi họp hôm nay, sếp không MENTION gì đến kế hoạch tăng lương, nên nhân viên có phần thất vọng.', 'Đề cập đến', 'beginner', 840),
  ('v506', 'notice', 'Khi Thu đổi kiểu tóc mới, bạn cùng lớp là người NOTICE đầu tiên và khen rất nhiều.', 'Nhận ra, để ý thấy', 'beginner', 810),
  ('v507', 'offer', 'Quán cà phê này OFFER chỗ ngồi ngoài trời cho khách đi cùng thú cưng vào buổi chiều.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v508', 'perceive', 'Nhiều người PERCEIVE khóa học online là dễ hơn lớp học trực tiếp, nhưng thực ra cần tự giác rất nhiều.', 'Nhận thức, nhìn nhận', 'intermediate', 1010),
  ('v509', 'quality', 'Quán bánh mì này nổi tiếng nhờ QUALITY nguyên liệu tươi và giá phải chăng, nên lúc nào cũng đông khách.', 'Chất lượng', 'beginner', 805),
  ('v510', 'recognize', 'Sau nhiều năm xa cách, tôi gần như không RECOGNIZE người bạn cũ khi gặp lại ở sân bay.', 'Nhận ra', 'beginner', 875),
  ('v511', 'sensitive', 'Đây là vấn đề khá SENSITIVE với gia đình, nên khi nói chuyện bạn nên nhẹ nhàng và tế nhị.', 'Nhạy cảm', 'intermediate', 935),
  ('v512', 'trustworthy', 'Trước khi thuê người giữ trẻ, chị Lan tìm hiểu kỹ để chắc chắn họ là người TRUSTWORTHY.', 'Đáng tin cậy', 'intermediate', 925),
  ('v513', 'unexpected', 'Buổi tối đang đọc sách thì có một cuộc gọi UNEXPECTED từ bạn học cũ, và hai người nói chuyện rất lâu.', 'Bất ngờ, không mong đợi', 'beginner', 850),
  ('v514', 'valuable', 'Những lời góp ý thẳng thắn của đồng nghiệp là VALUABLE, vì giúp tôi nhìn ra điểm yếu của mình.', 'Quý giá, có giá trị', 'beginner', 855),
  ('v515', 'willing', 'Bố luôn WILLING đưa con đến trường mỗi sáng, dù nhà cách trường khá xa.', 'Sẵn lòng, tự nguyện', 'beginner', 830),
  ('v516', 'annoying', 'Tiếng quảng cáo tự bật trên điện thoại thật sự ANNOYING, nhất là khi đang xem video.', 'Làm phiền, gây khó chịu', 'beginner', 820),
  ('v517', 'believable', 'Lời giải thích của anh ấy về việc đến trễ nghe khá BELIEVABLE vì hôm đó đường kẹt xe thật.', 'Có thể tin được', 'beginner', 815),
  ('v518', 'convenient', 'Siêu thị gần nhà rất CONVENIENT, lúc nào muốn mua đồ ăn tối cũng chỉ mất vài phút đi bộ.', 'Tiện lợi', 'beginner', 820),
  ('v519', 'doubt', 'Tôi DOUBT anh ấy sẽ trả lại tiền đúng hạn vì lần trước đã hẹn nhiều lần mà không làm.', 'Nghi ngờ', 'beginner', 855),
  ('v520', 'efficient', 'Nhóm họp nhanh 15 phút mỗi sáng là cách EFFICIENT để cập nhật tiến độ mà không mất thời gian.', 'Hiệu quả, năng suất', 'intermediate', 920)
insert into studio_core_cards (id, word, scenario, translation_hint, level, elo) values
  ('v521', 'frustrated', 'Đang soạn tin nhắn dài thì điện thoại bị đơ, Hùng cảm thấy FRUSTRATED và tắt máy luôn.', 'Bực bội, nản lòng', 'beginner', 870),
  ('v522', 'genuine', 'Lời xin lỗi của anh ấy nghe rất GENUINE, không giống mấy câu xã giao cho qua chuyện.', 'Thật lòng, chân thành', 'beginner', 880),
  ('v523', 'hesitate', 'Nếu bạn muốn đăng ký lớp tiếng Anh này, đừng HESITATE vì số lượng chỗ rất có hạn.', 'Do dự, ngập ngừng', 'beginner', 825),
  ('v524', 'influence', 'Thầy giáo cũ có INFLUENCE lớn đến cách tôi học tiếng Anh và chọn nghề sau này.', 'Ảnh hưởng, tác động', 'intermediate', 915),
  ('v525', 'judge', 'Bạn đừng JUDGE người khác qua bề ngoài, vì mỗi người đều có một hoàn cảnh riêng.', 'Đánh giá, phán xét', 'beginner', 830),
  ('v526', 'lack', 'Dự án này LACK nhân sự nên cả nhóm phải làm thêm vào cuối tuần để kịp tiến độ.', 'Thiếu hụt', 'beginner', 810),
  ('v527', 'maintain', 'Để MAINTAIN sức khỏe, anh Dũng đi bộ đều mỗi tối và ăn nhiều rau xanh hơn.', 'Duy trì, giữ vững', 'beginner', 865),
  ('v528', 'nervous', 'Trước buổi phỏng vấn đầu tiên, Mai NERVOUS đến mức không ăn nổi bữa sáng.', 'Lo lắng, hồi hộp', 'beginner', 815),
  ('v529', 'opportunity', 'Chương trình trao đổi sinh viên là một OPPORTUNITY tốt để em học hỏi và mở rộng kiến thức.', 'Cơ hội', 'beginner', 850),
  ('v530', 'prefer', 'Mình PREFER học buổi sáng vì đầu óc minh mẫn hơn, còn buổi tối thường hay mệt.', 'Thích hơn', 'beginner', 820),
  ('v531', 'quality', 'Khi chọn mua tai nghe, bạn nên xem QUALITY âm thanh và độ bền, không chỉ nhìn vào giá.', 'Chất lượng', 'beginner', 805),
  ('v532', 'recognize', 'Đứng giữa đám đông trước cổng trường, tôi không RECOGNIZE được bạn cũ dù đã hẹn trước.', 'Nhận ra', 'beginner', 875),
  ('v533', 'urgent', 'Bệnh viện gọi điện báo có ca URGENT cần bác sĩ có mặt ngay, nên anh ấy phải đổi lịch hẹn.', 'Khẩn cấp', 'beginner', 845),
  ('v534', 'admit', 'Cô ấy phải ADMIT rằng bài viết của mình chưa đủ rõ ràng và sẵn sàng sửa theo góp ý.', 'Thừa nhận', 'beginner', 865),
  ('v535', 'boring', 'Thứ Bảy mà không có kế hoạch gì thì đúng là BORING, nên mình rủ bạn đi xem triển lãm tranh.', 'Buồn chán', 'beginner', 800),
  ('v536', 'complain', 'Nếu bạn thấy phí dịch vụ không hợp lý, hãy COMPLAIN với bộ phận chăm sóc khách hàng để được giải quyết.', 'Than phiền, phàn nàn', 'beginner', 820),
  ('v537', 'force', 'Huấn luyện viên không nên FORCE học viên tập quá sức, vì như vậy sẽ không hiệu quả.', 'Ép buộc', 'beginner', 840),
  ('v538', 'hardly', 'Từ khi bắt đầu đi làm, Nam HARDLY có thời gian gọi điện cho gia đình ở quê.', 'Hầu như không', 'beginner', 815),
  ('v539', 'offer', 'Tiệm sách này OFFER giảm giá cho sinh viên mỗi thứ Tư, nên bạn nhớ mang theo thẻ sinh viên.', 'Đề nghị, mời chào', 'beginner', 850),
  ('v540', 'notice', 'Mình NOTICE bạn cùng phòng luôn để bếp rất sạch sẽ, nên mình muốn cảm ơn bạn.', 'Để ý thấy, nhận ra', 'beginner', 810)
